import React, { useState } from "react";
import { Card, Button, Form, Alert, Spinner } from "react-bootstrap";
import { authService } from "../../services";
import { ROLES } from "../../routes/permissions";

const MFAVerify = ({ user, onSuccess }) => {
  const [code, setCode] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [message, setMessage] = useState("");
  const [bypassLoading, setBypassLoading] = useState(false);
  const [bypassMessage, setBypassMessage] = useState("");

  const handleVerify = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError("");
    setMessage("");
    try {
      await authService.verifyMFA(user.email, code);
      setMessage("MFA verified!");
      onSuccess();
    } catch (e) {
      setError(e.response?.data?.message || "Invalid code");
    }
    setLoading(false);
  };

  const handleEmergencyBypass = async () => {
    setBypassLoading(true);
    setBypassMessage("");
    setError("");
    try {
      await authService.emergencyBypassMFA(user.email);
      setBypassMessage(
        "Emergency MFA bypass granted. This action has been logged.",
      );
      onSuccess();
    } catch (e) {
      setError(e.response?.data?.message || "Bypass failed");
    }
    setBypassLoading(false);
  };

  return (
    <div className="d-flex justify-content-center align-items-center min-vh-100 bg-light">
      <Card style={{ width: 350 }}>
        <Card.Body>
          <h4 className="mb-3 text-center">Multi-Factor Authentication</h4>
          {message && <Alert variant="success">{message}</Alert>}
          {error && <Alert variant="danger">{error}</Alert>}
          {bypassMessage && <Alert variant="warning">{bypassMessage}</Alert>}
          <Form onSubmit={handleVerify}>
            <Form.Group className="mb-3">
              <Form.Label>Enter MFA Code or Backup Code</Form.Label>
              <Form.Control
                value={code}
                onChange={(e) => setCode(e.target.value)}
                autoFocus
                autoComplete="one-time-code"
                placeholder="MFA or backup code"
              />
            </Form.Group>
            <Button
              type="submit"
              variant="primary"
              className="w-100 mb-2"
              disabled={loading}
            >
              {loading ? <Spinner animation="border" size="sm" /> : "Verify"}
            </Button>
          </Form>
          {user.role === ROLES.ADMIN && (
            <Button
              variant="outline-danger"
              className="w-100"
              onClick={handleEmergencyBypass}
              disabled={bypassLoading}
            >
              {bypassLoading ? "Processing..." : "Emergency MFA Bypass"}
            </Button>
          )}
        </Card.Body>
      </Card>
    </div>
  );
};

export default MFAVerify;
