import React, { useEffect, useRef, useState } from "react";
import { Card } from "react-bootstrap";
import { MapContainer as LeafletMap, TileLayer, Marker, Polyline, Popup, CircleMarker, useMap } from "react-leaflet";
import L from 'leaflet';
import "leaflet/dist/leaflet.css";

const GUJARAT_CENTER = [23.0225, 72.5714];
const DEMO_PATH = [
  [23.0225, 72.5714], // Ahmedabad
  [22.3072, 73.1812], // Vadodara
  [21.1702, 72.8311], // Surat
  [23.2156, 72.6369], // Gandhinagar
  [23.0225, 72.5714], // Ahmedabad (loop)
];
const defaultCenter = [22.9734, 78.6569]; // Center of India
const defaultZoom = 5;

const vehicleIcon = new L.Icon({
  iconUrl: 'https://cdn-icons-png.flaticon.com/512/936/936810.png',
  iconSize: [32, 32],
  iconAnchor: [25, 25],
});

function DemoVehicleMarker({ progress }) {
  // Interpolate between points for smooth animation
  const seg = Math.floor(progress);
  const nextSeg = (seg + 1) % DEMO_PATH.length;
  const frac = progress - seg;
  const start = DEMO_PATH[seg];
  const end = DEMO_PATH[nextSeg];
  const lat = start[0] + (end[0] - start[0]) * frac;
  const lng = start[1] + (end[1] - start[1]) * frac;
  return <Marker position={{ lat, lng }} icon={vehicleIcon} />;
}

const TripMap = ({ route, stops = [], playbackData = [], liveLocation, readOnly = false, demoMode = false }) => {
  // Extract coordinates for polyline
  const stopCoords = stops.map(s => [s.lat, s.lng]);
  // Optionally add live location to the polyline
  const routeCoords = liveLocation ? [...stopCoords, [liveLocation.lat, liveLocation.lng]] : stopCoords;

  // Demo animation state
  const [demoProgress, setDemoProgress] = useState(0);
  const demoInterval = useRef(null);
  useEffect(() => {
    if (!demoMode) return;
    demoInterval.current = setInterval(() => {
      setDemoProgress((p) => (p + 0.01) % (DEMO_PATH.length - 1));
    }, 100);
    return () => clearInterval(demoInterval.current);
  }, [demoMode]);

  return (
    <Card className="mb-3">
      <Card.Header>
        <h5 className="mb-0">Trip Map</h5>
      </Card.Header>
      <Card.Body>
        <div className="mb-2">
          <strong>Stops:</strong> {stops.length}
        </div>
        <div className="mb-2">
          <strong>Playback Points:</strong> {playbackData.length}
        </div>
        <div className="mb-2">
          <strong>Live Location:</strong> {liveLocation ? "Yes" : "No"}
        </div>
        <div className="border rounded p-1" style={{ minHeight: 320, height: 320 }}>
          {demoMode ? (
            <LeafletMap center={GUJARAT_CENTER} zoom={8} style={{ height: "100%", width: "100%" }} scrollWheelZoom={false} dragging={true}>
              <TileLayer
                url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
                attribution="&copy; OpenStreetMap contributors"
              />
              <Polyline positions={DEMO_PATH} color="#3b82f6" weight={4} />
              <DemoVehicleMarker progress={demoProgress} />
            </LeafletMap>
          ) : (
            <LeafletMap center={defaultCenter} zoom={defaultZoom} style={{ height: "100%", width: "100%" }} scrollWheelZoom={false}>
              <TileLayer
                attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
                url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
              />
              {/* Route polyline */}
              {routeCoords.length > 1 && (
                <Polyline positions={routeCoords} color="#6366f1" weight={5} />
              )}
              {/* Stops as markers */}
              {stops.map((stop, i) => (
                <Marker key={i} position={[stop.lat, stop.lng]}>
                  <Popup>
                    <strong>{stop.name}</strong><br />{stop.address}
                  </Popup>
                </Marker>
              ))}
              {/* Live location as a green circle marker */}
              {liveLocation && (
                <CircleMarker center={[liveLocation.lat, liveLocation.lng]} radius={12} color="#22c55e" fillColor="#22c55e" fillOpacity={0.7}>
                  <Popup>
                    <strong>Live Location</strong><br />Lat: {liveLocation.lat}, Lng: {liveLocation.lng}
                  </Popup>
                </CircleMarker>
              )}
            </LeafletMap>
          )}
        </div>
      </Card.Body>
    </Card>
  );
};

export default TripMap; 