import React, { useState, useEffect } from 'react';
import { useSelector } from 'react-redux';

const AlertsPanel = ({ alerts = [] }) => {
  const [localAlerts, setLocalAlerts] = useState([]);
  const connectionStatus = useSelector(state => state.tracking.connectionStatus);

  // Mock real-time alerts for demonstration
  useEffect(() => {
    if (connectionStatus !== 'connected') return;

    const mockAlerts = [
      {
        id: '1',
        type: 'geofence_violation',
        vehicleId: 'vehicle-1',
        vehicleName: 'Truck 001',
        message: 'Vehicle entered restricted zone',
        timestamp: new Date(Date.now() - 5 * 60 * 1000), // 5 minutes ago
        severity: 'warning',
        acknowledged: false
      },
      {
        id: '2',
        type: 'speed_alert',
        vehicleId: 'vehicle-2',
        vehicleName: 'Van 002',
        message: 'Speed limit exceeded (75 mph in 55 mph zone)',
        timestamp: new Date(Date.now() - 2 * 60 * 1000), // 2 minutes ago
        severity: 'high',
        acknowledged: false
      },
      {
        id: '3',
        type: 'device_status',
        vehicleId: 'vehicle-3',
        vehicleName: 'Car 003',
        message: 'GPS device offline',
        timestamp: new Date(Date.now() - 10 * 60 * 1000), // 10 minutes ago
        severity: 'critical',
        acknowledged: true
      }
    ];

    setLocalAlerts(mockAlerts);
  }, [connectionStatus]);

  const getSeverityColor = (severity) => {
    switch (severity) {
      case 'critical': return '#dc2626';
      case 'high': return '#ea580c';
      case 'warning': return '#d97706';
      case 'info': return '#3b82f6';
      default: return '#6b7280';
    }
  };

  const getSeverityIcon = (severity) => {
    switch (severity) {
      case 'critical': return '🚨';
      case 'high': return '⚠️';
      case 'warning': return '⚠️';
      case 'info': return 'ℹ️';
      default: return '📋';
    }
  };

  const getTypeIcon = (type) => {
    switch (type) {
      case 'geofence_violation': return '📍';
      case 'speed_alert': return '🚗';
      case 'device_status': return '📱';
      default: return '🔔';
    }
  };

  const handleAcknowledge = (alertId) => {
    setLocalAlerts(prev => 
      prev.map(alert => 
        alert.id === alertId 
          ? { ...alert, acknowledged: true }
          : alert
      )
    );
  };

  const unacknowledgedAlerts = localAlerts.filter(alert => !alert.acknowledged);
  const acknowledgedAlerts = localAlerts.filter(alert => alert.acknowledged);

  return (
    <div className="alerts-panel" style={{
      background: '#fff',
      border: '1px solid #e5e7eb',
      borderRadius: '8px',
      padding: '16px',
      maxHeight: '600px',
      overflowY: 'auto'
    }}>
      <div style={{ 
        display: 'flex', 
        justifyContent: 'space-between', 
        alignItems: 'center',
        marginBottom: '16px'
      }}>
        <h3 style={{ margin: 0, fontSize: '18px', fontWeight: '600' }}>
          Alerts ({unacknowledgedAlerts.length})
        </h3>
        <div style={{ 
          fontSize: '12px', 
          color: connectionStatus === 'connected' ? '#22c55e' : '#ef4444',
          fontWeight: '500'
        }}>
          {connectionStatus === 'connected' ? '● Live' : '● Offline'}
        </div>
      </div>

      {unacknowledgedAlerts.length === 0 && acknowledgedAlerts.length === 0 && (
        <div style={{ 
          textAlign: 'center', 
          color: '#6b7280', 
          padding: '20px',
          fontSize: '14px'
        }}>
          No alerts at this time
        </div>
      )}

      {/* Unacknowledged Alerts */}
      {unacknowledgedAlerts.length > 0 && (
        <div style={{ marginBottom: '16px' }}>
          <h4 style={{ 
            margin: '0 0 12px 0', 
            fontSize: '14px', 
            fontWeight: '600',
            color: '#dc2626'
          }}>
            Active Alerts ({unacknowledgedAlerts.length})
          </h4>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
            {unacknowledgedAlerts.map(alert => (
              <div key={alert.id} style={{
                border: `2px solid ${getSeverityColor(alert.severity)}`,
                borderRadius: '6px',
                padding: '12px',
                background: '#fef2f2'
              }}>
                <div style={{ 
                  display: 'flex', 
                  justifyContent: 'space-between', 
                  alignItems: 'flex-start',
                  marginBottom: '8px'
                }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                    <span style={{ fontSize: '16px' }}>
                      {getTypeIcon(alert.type)}
                    </span>
                    <span style={{ fontSize: '16px' }}>
                      {getSeverityIcon(alert.severity)}
                    </span>
                    <span style={{ 
                      fontWeight: '600', 
                      fontSize: '14px',
                      color: '#111827'
                    }}>
                      {alert.vehicleName}
                    </span>
                  </div>
                  <button
                    onClick={() => handleAcknowledge(alert.id)}
                    style={{
                      background: '#3b82f6',
                      color: 'white',
                      border: 'none',
                      padding: '4px 8px',
                      borderRadius: '4px',
                      fontSize: '12px',
                      cursor: 'pointer'
                    }}
                  >
                    Acknowledge
                  </button>
                </div>
                
                <div style={{ 
                  fontSize: '13px', 
                  color: '#374151',
                  marginBottom: '4px'
                }}>
                  {alert.message}
                </div>
                
                <div style={{ 
                  fontSize: '11px', 
                  color: '#6b7280'
                }}>
                  {alert.timestamp.toLocaleTimeString()} • {alert.severity.toUpperCase()}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Acknowledged Alerts */}
      {acknowledgedAlerts.length > 0 && (
        <div>
          <h4 style={{ 
            margin: '0 0 12px 0', 
            fontSize: '14px', 
            fontWeight: '600',
            color: '#6b7280'
          }}>
            Acknowledged ({acknowledgedAlerts.length})
          </h4>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
            {acknowledgedAlerts.map(alert => (
              <div key={alert.id} style={{
                border: '1px solid #e5e7eb',
                borderRadius: '6px',
                padding: '10px',
                background: '#f9fafb',
                opacity: 0.7
              }}>
                <div style={{ 
                  display: 'flex', 
                  alignItems: 'center', 
                  gap: '8px',
                  marginBottom: '4px'
                }}>
                  <span style={{ fontSize: '14px' }}>
                    {getTypeIcon(alert.type)}
                  </span>
                  <span style={{ 
                    fontWeight: '500', 
                    fontSize: '13px',
                    color: '#374151'
                  }}>
                    {alert.vehicleName}
                  </span>
                </div>
                
                <div style={{ 
                  fontSize: '12px', 
                  color: '#6b7280'
                }}>
                  {alert.message}
                </div>
                
                <div style={{ 
                  fontSize: '11px', 
                  color: '#9ca3af',
                  marginTop: '2px'
                }}>
                  {alert.timestamp.toLocaleTimeString()} • Acknowledged
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default AlertsPanel; 