import React from "react";
import { Card, Button, Table, Badge } from "react-bootstrap";

const statusVariant = (status) => {
  if (status === "VALID") return "success";
  if (status === "EXPIRING_SOON") return "warning";
  if (status === "EXPIRED") return "danger";
  return "secondary";
};

const VehicleDocumentManager = ({ documents = [], onUpload, onDelete }) => {
  return (
    <Card className="mb-3">
      <Card.Body>
        <Card.Title>Vehicle Documents</Card.Title>
        <Table striped bordered hover className="mt-3">
          <thead>
            <tr>
              <th>Type</th>
              <th>Number</th>
              <th>Issue Date</th>
              <th>Expiry Date</th>
              <th>Issuing Authority</th>
              <th>Status</th>
              <th>File</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {documents.map((doc) => (
              <tr key={doc.documentId}>
                <td>{doc.documentType}</td>
                <td>{doc.documentNumber}</td>
                <td>{doc.issueDate}</td>
                <td>{doc.expiryDate}</td>
                <td>{doc.issuingAuthority}</td>
                <td>
                  <Badge bg={statusVariant(doc.status)}>{doc.status}</Badge>
                </td>
                <td>
                  {doc.fileUrl ? (
                    <a
                      href={doc.fileUrl}
                      target="_blank"
                      rel="noopener noreferrer"
                    >
                      View
                    </a>
                  ) : (
                    "-"
                  )}
                </td>
                <td>
                  {onDelete && (
                    <Button
                      size="sm"
                      variant="danger"
                      onClick={() => onDelete(doc.documentId)}
                    >
                      Delete
                    </Button>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </Table>
        <Button className="mt-2" onClick={onUpload}>
          Upload Document
        </Button>
      </Card.Body>
    </Card>
  );
};

export default VehicleDocumentManager;
