import React, { useEffect, useState } from "react";
import { Card, Button, Table, Spinner, Alert, Modal, Form } from "react-bootstrap";
import { getVehicleAssignments, assignVehicle, unassignVehicle, addVehicleAuditLog } from "../../../services/vehicle.service";
import { useAuth } from "../../../hooks/useAuth";
import { usePermissions } from "../../../hooks/usePermissions";
import { PERMISSIONS } from "../../../routes/permissions";

const VehicleAssignmentManager = ({ vehicleId }) => {
  const [assignments, setAssignments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [showAssignModal, setShowAssignModal] = useState(false);
  const [form, setForm] = useState({ driverId: "", routeId: "" });
  const { user } = useAuth();
  const { hasPermission } = usePermissions();

  useEffect(() => {
    setLoading(true);
    getVehicleAssignments(vehicleId)
      .then((res) => {
        setAssignments(res.data);
        setLoading(false);
      })
      .catch((err) => {
        setError("Failed to load assignments");
        setLoading(false);
      });
  }, [vehicleId]);

  const handleAssign = async () => {
    setLoading(true);
    setError("");
    try {
      const res = await assignVehicle({ vehicleId, ...form });
      setAssignments((prev) => [...prev, res.data]);
      await addVehicleAuditLog(vehicleId, user?.userId, "assign", { driverId: form.driverId, routeId: form.routeId });
      setShowAssignModal(false);
      setForm({ driverId: "", routeId: "" });
    } catch (err) {
      setError("Failed to assign vehicle");
    } finally {
      setLoading(false);
    }
  };

  const handleUnassign = async (assignmentId) => {
    setLoading(true);
    setError("");
    try {
      const res = await unassignVehicle(assignmentId);
      setAssignments((prev) => prev.map((a) => a.assignmentId === assignmentId ? res.data : a));
      await addVehicleAuditLog(vehicleId, user?.userId, "unassign", { assignmentId });
    } catch (err) {
      setError("Failed to unassign vehicle");
    } finally {
      setLoading(false);
    }
  };

  return (
    <Card className="mb-3">
      <Card.Body>
        <Card.Title>Vehicle Assignment</Card.Title>
        {loading && <Spinner animation="border" />}
        {error && <Alert variant="danger">{error}</Alert>}
        <Table striped bordered hover className="mt-3">
          <thead>
            <tr>
              <th>Vehicle ID</th>
              <th>Driver ID</th>
              <th>Route ID</th>
              <th>Assigned Date</th>
              <th>Unassigned Date</th>
              <th>Status</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {assignments.map((a) => (
              <tr key={a.assignmentId}>
                <td>{a.vehicleId}</td>
                <td>{a.driverId}</td>
                <td>{a.routeId}</td>
                <td>{a.assignedDate}</td>
                <td>{a.unassignedDate || "-"}</td>
                <td>{a.status}</td>
                <td>
                  {hasPermission(PERMISSIONS.VEHICLE_ASSIGNMENT) && a.status === "ASSIGNED" && (
                    <Button
                      size="sm"
                      variant="danger"
                      onClick={() => handleUnassign(a.assignmentId)}
                      disabled={loading}
                    >
                      Unassign
                    </Button>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </Table>
        {hasPermission(PERMISSIONS.VEHICLE_ASSIGNMENT) && (
          <Button className="mt-2" onClick={() => setShowAssignModal(true)} disabled={loading}>
            Assign Driver/Route
          </Button>
        )}
        <Modal show={showAssignModal} onHide={() => setShowAssignModal(false)} centered backdrop="static">
          <Modal.Header closeButton>
            <Modal.Title>Assign Driver/Route</Modal.Title>
          </Modal.Header>
          <Modal.Body>
            <Form>
              <Form.Group className="mb-2">
                <Form.Label>Driver ID</Form.Label>
                <Form.Control
                  name="driverId"
                  value={form.driverId}
                  onChange={(e) => setForm({ ...form, driverId: e.target.value })}
                  required
                />
              </Form.Group>
              <Form.Group className="mb-2">
                <Form.Label>Route ID</Form.Label>
                <Form.Control
                  name="routeId"
                  value={form.routeId}
                  onChange={(e) => setForm({ ...form, routeId: e.target.value })}
                />
              </Form.Group>
            </Form>
          </Modal.Body>
          <Modal.Footer>
            <Button variant="secondary" onClick={() => setShowAssignModal(false)}>
              Cancel
            </Button>
            <Button variant="primary" onClick={handleAssign} disabled={loading || !form.driverId}>
              {loading ? <Spinner size="sm" animation="border" /> : "Assign"}
            </Button>
          </Modal.Footer>
        </Modal>
      </Card.Body>
    </Card>
  );
};

export default VehicleAssignmentManager;
