import React from "react";
import { useParams, useNavigate } from "react-router-dom";
import TripDetails from "./TripDetails";
import { Card, Button, Container, Row, Col, Badge, ListGroup, ProgressBar } from "react-bootstrap";
import { ArrowLeft, GeoAlt, Person, Truck, Tag, Clock } from 'react-bootstrap-icons';
import './TripViewPage.css'; // For custom styles (create this file if needed)
import TripMap from "./TripMap";
import RoutePlayback from "./RoutePlayback";
import TripAlertsPanel from "./TripAlertsPanel";
import { Tabs, Tab } from "react-bootstrap";
import RoutePlanner from "./RoutePlanner";

// TODO: Replace with real data fetching
const dummyTrips = [
  {
    id: "1",
    title: "Delhi to Mumbai Delivery",
    description: "Urgent delivery of electronics from Delhi to Mumbai.",
    createdBy: { id: 1, name: "Development Team", type: "team" },
    permissions: ["team_create", "edit", "view"],
    vehicle: { id: 1, name: "Truck 101", status: "AVAILABLE" },
    driver: { id: 1, name: "John Doe", location: { lat: 28.61, lng: 77.23 } },
    source: { name: "Delhi Warehouse", address: "Delhi, India", lat: 28.61, lng: 77.23, partyInfo: "Acme Corp" },
    destination: { name: "Mumbai Hub", address: "Mumbai, India", lat: 19.07, lng: 72.87, partyInfo: "Beta Solutions" },
    stops: [
      { id: 1, name: "Agra Stop", address: "Agra, India", lat: 27.18, lng: 78.01, scheduledTime: "2024-06-01T10:00", actualTime: null },
      { id: 2, name: "Surat Stop", address: "Surat, India", lat: 21.17, lng: 72.83, scheduledTime: "2024-06-01T18:00", actualTime: null },
    ],
    route: { id: 1, name: "Delhi-Mumbai Route", waypoints: [], optimized: true },
    playback: { available: true, data: [] },
    liveLocation: { lat: 24.5, lng: 75.0, timestamp: "2024-06-01T12:00" },
    analytics: {
      distance: 1400,
      duration: 24,
      speedStats: { avg: 60, max: 90, overspeedEvents: [] },
      alerts: [
        { type: "overspeeding", message: "Driver exceeded speed limit.", timestamp: "2024-06-01T11:00" },
        { type: "geo fencing breach", message: "Vehicle left geofenced area.", timestamp: "2024-06-01T11:30" },
      ],
    },
    events: [
      { type: "start", message: "Trip started from Delhi Warehouse.", timestamp: "2024-06-01T09:00" },
      { type: "stop", message: "Stopped at Agra Stop.", timestamp: "2024-06-01T10:30" },
      { type: "resume", message: "Resumed from Agra Stop.", timestamp: "2024-06-01T11:00" },
      { type: "stop", message: "Stopped at Surat Stop.", timestamp: "2024-06-01T18:30" },
      { type: "end", message: "Arrived at Mumbai Hub.", timestamp: "2024-06-02T08:00" },
    ],
    status: "LIVE",
    schedule: { type: "one-time", cron: "", nextRun: null },
    tags: ["electronics", "urgent"],
    instant: false,
    autoCreated: false,
    createdAt: "2024-05-31T09:00",
    updatedAt: "2024-06-01T12:00",
  },
];

const TripViewPage = () => {
  const { tripId } = useParams();
  const navigate = useNavigate();
  // TODO: Fetch trip by ID
  const trip = dummyTrips.find((t) => t.id === tripId) || dummyTrips[0];

  return (
    <Container fluid className="py-4 trip-view-modern-bg" style={{ minHeight: "100vh" }}>
      {/* Back Button */}
      <Row className="mb-2">
        <Col xs="auto">
          <Button variant="outline-dark" onClick={() => navigate("/trips")}
            style={{ borderRadius: 16, fontWeight: 600, boxShadow: '0 2px 8px #0001' }}>
            <ArrowLeft size={22} className="me-2" /> Back
          </Button>
        </Col>
      </Row>
      {/* Header Card: Title, Status, Tags */}
      <Row className="mb-4">
        <Col md={12}>
          <Card className="shadow-lg border-0" style={{ borderRadius: 24, background: 'linear-gradient(135deg, #f8fafc 60%, #e0e7ff 100%)' }}>
            <Card.Body className="d-flex flex-column flex-md-row align-items-md-center justify-content-between">
              <div>
                <h2 style={{ fontWeight: 900, color: "#1a1a1a", letterSpacing: 1, fontSize: '2.2rem', textShadow: '0 2px 8px #0001' }}>{trip.title}</h2>
                <div className="mt-2">
                  <Badge bg="success" className="me-2">{trip.status}</Badge>
                  {trip.tags?.map(tag => <Badge bg="info" key={tag} className="me-1">{tag}</Badge>)}
                </div>
              </div>
              <div className="mt-3 mt-md-0">
                <span className="text-muted me-3"><strong>Created:</strong> {trip.createdAt ? new Date(trip.createdAt).toLocaleString() : "-"}</span>
                <span className="text-muted"><strong>Updated:</strong> {trip.updatedAt ? new Date(trip.updatedAt).toLocaleString() : "-"}</span>
              </div>
            </Card.Body>
          </Card>
        </Col>
      </Row>
      {/* Main Content */}
      <Row>
        <Col md={8}>
          <Card className="mb-4 shadow-sm border-0" style={{ borderRadius: 20 }}>
            <Card.Body>
              <Tabs defaultActiveKey="details" id="trip-tabs" className="mb-3">
                <Tab eventKey="details" title="Trip Details">
                  {/* Timeline Section */}
                  <h5 className="fw-bold mb-3" style={{ color: '#6366f1' }}>Trip Timeline</h5>
                  <ListGroup variant="flush" className="trip-timeline-list">
                    <ListGroup.Item className="bg-transparent border-0 ps-0">
                      <GeoAlt className="me-2 text-danger" /> <strong>Start:</strong> {trip.source?.name}
                    </ListGroup.Item>
                    {trip.stops?.map((stop, idx) => (
                      <ListGroup.Item key={idx} className="bg-transparent border-0 ps-4">
                        <GeoAlt className="me-2 text-warning" /> <strong>Stop {idx + 1}:</strong> {stop.name}
                        <div className="text-muted small ms-4">{stop.address}</div>
                      </ListGroup.Item>
                    ))}
                    <ListGroup.Item className="bg-transparent border-0 ps-0">
                      <GeoAlt className="me-2 text-success" /> <strong>End:</strong> {trip.destination?.name}
                    </ListGroup.Item>
                  </ListGroup>
                  <ProgressBar now={100} style={{ height: 8, borderRadius: 8, background: '#e0e7ff' }} className="mt-3 mb-4" />
                  {/* Trip Details Section */}
                  <h5 className="fw-bold mb-3 mt-4" style={{ color: '#6366f1' }}>Trip Details</h5>
                  <TripDetails trip={trip} />
                </Tab>
                <Tab eventKey="playback" title="Route Playback">
                  <RoutePlayback route={trip.route} playbackData={trip.playback?.data} stops={trip.stops} demoMode={true} />
                </Tab>
                <Tab eventKey="map" title="Trip Map">
                  <TripMap route={trip.route} stops={trip.stops} playbackData={trip.playback?.data} liveLocation={trip.liveLocation} demoMode={true} />
                </Tab>
                <Tab eventKey="live" title="Live Location">
                  <Card className="mb-3">
                    <Card.Header><h5 className="mb-0">Live Location</h5></Card.Header>
                    <Card.Body>
                      {trip.liveLocation ? (
                        <>
                          <div><strong>Latitude:</strong> {trip.liveLocation.lat}</div>
                          <div><strong>Longitude:</strong> {trip.liveLocation.lng}</div>
                          <div><strong>Timestamp:</strong> {trip.liveLocation.timestamp}</div>
                        </>
                      ) : (
                        <div className="text-muted">No live location data</div>
                      )}
                    </Card.Body>
                  </Card>
                </Tab>
                <Tab eventKey="analytics" title="Analytics">
                  <Card className="mb-3">
                    <Card.Header><h5 className="mb-0">Analytics</h5></Card.Header>
                    <Card.Body>
                      <table className="table table-bordered table-sm mb-3" style={{ maxWidth: 400 }}>
                        <tbody>
                          <tr>
                            <th>Distance</th>
                            <td>{trip.analytics?.distance ? `${trip.analytics.distance} km` : "-"}</td>
                          </tr>
                          <tr>
                            <th>Duration</th>
                            <td>{trip.analytics?.duration ? `${trip.analytics.duration} hrs` : "-"}</td>
                          </tr>
                          <tr>
                            <th>Avg Speed</th>
                            <td>{trip.analytics?.speedStats?.avg ? `${trip.analytics.speedStats.avg} km/h` : "-"}</td>
                          </tr>
                          <tr>
                            <th>Max Speed</th>
                            <td>{trip.analytics?.speedStats?.max ? `${trip.analytics.speedStats.max} km/h` : "-"}</td>
                          </tr>
                          <tr>
                            <th>Overspeed Events</th>
                            <td>{trip.analytics?.speedStats?.overspeedEvents?.length || 0}</td>
                          </tr>
                        </tbody>
                      </table>
                    </Card.Body>
                  </Card>
                </Tab>
                <Tab eventKey="planning" title="Planning">
                  <RoutePlanner route={trip.route} stops={trip.stops} readOnly />
                </Tab>
                <Tab eventKey="events" title="Events">
                  <Card className="mb-3">
                    <Card.Header><h5 className="mb-0">Events</h5></Card.Header>
                    <Card.Body>
                      {trip.events && trip.events.length > 0 ? (
                        <ListGroup>
                          {trip.events.map((event, idx) => (
                            <ListGroup.Item key={idx}>
                              <strong className="me-2">{event.type.toUpperCase()}</strong>
                              {event.message}
                              <span className="text-muted ms-2">({event.timestamp})</span>
                            </ListGroup.Item>
                          ))}
                        </ListGroup>
                      ) : (
                        <div className="text-muted">No events recorded for this trip.</div>
                      )}
                    </Card.Body>
                  </Card>
                </Tab>
                <Tab eventKey="alerts" title="Alerts">
                  <TripAlertsPanel alerts={trip.analytics?.alerts || []} />
                </Tab>
              </Tabs>
            </Card.Body>
          </Card>
        </Col>
        {/* Right: Vehicle, Driver, Meta Info */}
        <Col md={4}>
          <Card className="mb-4 shadow-sm border-0" style={{ borderRadius: 20, background: 'linear-gradient(135deg, #fffbe6 60%, #f0fff4 100%)' }}>
            <Card.Body>
              <h6 className="fw-bold mb-3" style={{ color: '#f59e42' }}>Assignment</h6>
              <div className="mb-3">
                <Truck className="me-2 text-primary" size={20} /> <strong>Vehicle:</strong> {trip.vehicle?.name}
              </div>
              <div className="mb-3">
                <Person className="me-2 text-info" size={20} /> <strong>Driver:</strong> {trip.driver?.name}
              </div>
              <hr />
              <h6 className="fw-bold mb-3" style={{ color: '#6366f1' }}>Meta Info</h6>
              <div className="mb-2">
                <Tag className="me-2 text-warning" size={20} /> <strong>Tags:</strong> {trip.tags?.map(tag => <Badge bg="info" key={tag} className="ms-1">{tag}</Badge>)}
              </div>
              <div className="mb-2">
                <Clock className="me-2 text-secondary" size={20} /> <strong>Status:</strong> <Badge bg="success" className="ms-1">{trip.status}</Badge>
              </div>
            </Card.Body>
          </Card>
        </Col>
      </Row>
    </Container>
  );
};

export default TripViewPage; 