import React from "react";
import { Card, Badge, Button, ListGroup } from "react-bootstrap";

const alertColors = {
  overspeeding: "danger",
  "route mismatch": "warning",
  "geo fencing breach": "info",
  default: "secondary",
};

const TripAlertsPanel = ({ alerts = [], onAcknowledge }) => {
  return (
    <Card>
      <Card.Header>
        <h5 className="mb-0">Trip Alerts</h5>
      </Card.Header>
      <Card.Body>
        {alerts.length === 0 ? (
          <div className="text-muted">No alerts</div>
        ) : (
          <ListGroup>
            {alerts.map((alert, idx) => (
              <ListGroup.Item key={idx} className="d-flex justify-content-between align-items-center">
                <div>
                  <Badge bg={alertColors[alert.type] || alertColors.default} className="me-2">
                    {alert.type}
                  </Badge>
                  {alert.message}
                  <span className="text-muted ms-2">({alert.timestamp})</span>
                </div>
                <Button
                  size="sm"
                  variant="outline-success"
                  onClick={() => onAcknowledge && onAcknowledge(alert)}
                >
                  Acknowledge
                </Button>
              </ListGroup.Item>
            ))}
          </ListGroup>
        )}
      </Card.Body>
    </Card>
  );
};

export default TripAlertsPanel; 