import React, { useEffect, useState, useRef } from "react";
import {
  Card,
  Form,
  Button,
  Spinner,
  Alert,
  Row,
  Col,
  Image,
} from "react-bootstrap";
import { getUserProfile, updateUserProfile } from "../../services";
import { useAuth } from "../../hooks/useAuth";
import { authService } from "../../services";
import AccountCircleIcon from "@mui/icons-material/AccountCircle";

const genzGradient = "linear-gradient(135deg, #667eea 0%, #f093fb 100%)";

const UserProfile = () => {
  const { user } = useAuth();
  const [profile, setProfile] = useState(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState("");
  const [edit, setEdit] = useState(false);
  const [form, setForm] = useState({});
  const [loginAttempts, setLoginAttempts] = useState([]);
  const [sessions, setSessions] = useState([]);
  const [avatar, setAvatar] = useState("");
  const [avatarFile, setAvatarFile] = useState(null);
  const fileInputRef = useRef();

  useEffect(() => {
    if (user) {
      getUserProfile(user.id)
        .then((res) => {
          setProfile(res.data);
          setForm(res.data);
          setAvatar(res.data.profilePhoto || "");
          setLoading(false);
        })
        .catch(() => setLoading(false));
      // Fetch recent login attempts
      setLoginAttempts(authService.getLoginAttempts(user.email).slice(0, 5));
      // Fetch active sessions
      authService.getSessions(user.email).then((res) => setSessions(res.data));
    }
  }, [user]);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleAvatarChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      setAvatarFile(file);
      const reader = new FileReader();
      reader.onload = (ev) => setAvatar(ev.target.result);
      reader.readAsDataURL(file);
    }
  };

  const handleSave = async () => {
    setSaving(true);
    setMessage("");
    try {
      // In a real app, upload avatarFile to server and get URL
      const updated = { ...form, profilePhoto: avatar };
      const res = await updateUserProfile(user.id, updated);
      setProfile(res.data);
      setEdit(false);
      setMessage("Profile updated successfully");
    } catch (e) {
      setMessage(e.response?.data?.message || "Error updating profile");
    }
    setSaving(false);
  };

  if (loading)
    return (
      <div className="d-flex justify-content-center align-items-center min-vh-100">
        <Spinner animation="border" />
      </div>
    );

  return (
    <div
      className="d-flex justify-content-center align-items-center min-vh-100"
      style={{ background: "var(--neutral-light)" }}
    >
      <Card
        className="shadow-lg p-4 genz-glass"
        style={{
          maxWidth: 600,
          width: "100%",
          borderRadius: 24,
          border: "none",
          background: "rgba(255,255,255,0.85)",
        }}
      >
        <div className="d-flex flex-column align-items-center mb-4">
          <div className="position-relative mb-2">
            {avatar ? (
              <Image
                src={avatar}
                roundedCircle
                style={{
                  width: 100,
                  height: 100,
                  objectFit: "cover",
                  border: "4px solid var(--primary)",
                  background: "var(--neutral-light)",
                }}
              />
            ) : (
              <div
                style={{
                  width: 100,
                  height: 100,
                  borderRadius: "50%",
                  background: "var(--primary)",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  border: "4px solid var(--primary)",
                }}
              >
                <AccountCircleIcon
                  style={{ fontSize: 80, color: "var(--neutral-light)" }}
                />
              </div>
            )}
            {edit && (
              <Button
                variant="light"
                size="sm"
                className="position-absolute bottom-0 end-0 rounded-circle border shadow"
                style={{
                  background: "var(--neutral-light)",
                  color: "var(--primary)",
                  padding: 6,
                }}
                onClick={() => fileInputRef.current.click()}
              >
                <span className="material-icons" style={{ fontSize: 20 }}>
                  photo_camera
                </span>
                <input
                  type="file"
                  accept="image/*"
                  ref={fileInputRef}
                  style={{ display: "none" }}
                  onChange={handleAvatarChange}
                />
              </Button>
            )}
          </div>
          <h4 className="fw-bold mb-0" style={{ color: "var(--primary)" }}>
            {profile.firstName || ""} {profile.lastName || ""}
          </h4>
          <div className="text-muted">{user.email}</div>
          <div
            className="badge rounded-pill px-3 py-2 mt-2"
            style={{
              background: "var(--primary)",
              color: "var(--neutral-light)",
              fontWeight: 500,
              fontSize: 14,
            }}
          >
            {user.role?.replace("_", " ").toUpperCase()}
          </div>
        </div>
        {message && <Alert variant="info">{message}</Alert>}
        <Form className="mb-4">
          <Row>
            <Col md={6} className="mb-3">
              <Form.Group>
                <Form.Label>First Name</Form.Label>
                <Form.Control
                  name="firstName"
                  value={form.firstName || ""}
                  onChange={handleChange}
                  disabled={!edit}
                />
              </Form.Group>
            </Col>
            <Col md={6} className="mb-3">
              <Form.Group>
                <Form.Label>Last Name</Form.Label>
                <Form.Control
                  name="lastName"
                  value={form.lastName || ""}
                  onChange={handleChange}
                  disabled={!edit}
                />
              </Form.Group>
            </Col>
          </Row>
          <Row>
            <Col md={6} className="mb-3">
              <Form.Group>
                <Form.Label>Phone</Form.Label>
                <Form.Control
                  name="phone"
                  value={form.phone || ""}
                  onChange={handleChange}
                  disabled={!edit}
                />
              </Form.Group>
            </Col>
            <Col md={6} className="mb-3">
              <Form.Group>
                <Form.Label>Company</Form.Label>
                <Form.Control
                  name="company"
                  value={form.company || ""}
                  onChange={handleChange}
                  disabled={!edit}
                />
              </Form.Group>
            </Col>
          </Row>
          <Form.Group className="mb-3">
            <Form.Label>Address</Form.Label>
            <Form.Control
              name="address"
              value={form.address || ""}
              onChange={handleChange}
              disabled={!edit}
            />
          </Form.Group>
        </Form>
        <div className="mb-4 text-center">
          {!edit ? (
            <Button
              onClick={() => setEdit(true)}
              className="rounded-pill px-4 py-2"
              style={{ background: "var(--primary)", border: "none" }}
            >
              Edit Profile
            </Button>
          ) : (
            <>
              <Button
                onClick={handleSave}
                disabled={saving}
                className="rounded-pill px-4 py-2 me-2"
                style={{ background: "var(--primary)", border: "none" }}
              >
                {saving ? "Saving..." : "Save"}
              </Button>
              <Button
                variant="secondary"
                className="rounded-pill px-4 py-2"
                onClick={() => {
                  setEdit(false);
                  setForm(profile);
                  setAvatar(profile.profilePhoto || "");
                }}
              >
                Cancel
              </Button>
            </>
          )}
        </div>
        <Row>
          <Col md={6} className="mb-3">
            <Card className="h-100 shadow-sm border-0">
              <Card.Body>
                <Card.Title className="fs-6 mb-3">
                  Recent Login Attempts
                </Card.Title>
                <ul className="list-group list-group-flush">
                  {loginAttempts.length === 0 && (
                    <li className="list-group-item">No recent attempts.</li>
                  )}
                  {loginAttempts.map((a, idx) => (
                    <li
                      key={idx}
                      className={`list-group-item d-flex justify-content-between align-items-center ${a.success ? "list-group-item-success" : "list-group-item-danger"}`}
                      style={{ fontSize: 14 }}
                    >
                      <span>
                        {new Date(a.timestamp).toLocaleString()}
                        <br />
                        <span className="text-muted">{a.ip}</span>
                      </span>
                      <span>{a.success ? "Success" : "Failed"}</span>
                    </li>
                  ))}
                </ul>
              </Card.Body>
            </Card>
          </Col>
          <Col md={6} className="mb-3">
            <Card className="h-100 shadow-sm border-0">
              <Card.Body>
                <Card.Title className="fs-6 mb-3">Active Sessions</Card.Title>
                <ul className="list-group list-group-flush">
                  {sessions.length === 0 && (
                    <li className="list-group-item">No active sessions.</li>
                  )}
                  {sessions.map((s, idx) => (
                    <li
                      key={idx}
                      className="list-group-item d-flex justify-content-between align-items-center"
                      style={{ fontSize: 14 }}
                    >
                      <span>
                        Session: {s.token.slice(-8)}
                        <br />
                        <span className="text-muted">
                          {new Date(s.created).toLocaleString()}
                        </span>
                      </span>
                      {localStorage.getItem("token") === s.token && (
                        <span className="badge bg-primary">Current</span>
                      )}
                    </li>
                  ))}
                </ul>
                {sessions.length > 1 && (
                  <Button
                    className="mt-2 rounded-pill px-3 py-1"
                    size="sm"
                    style={{ background: "var(--primary)", border: "none" }}
                    onClick={async () => {
                      await authService.invalidateOtherSessions(
                        user.email,
                        localStorage.getItem("token"),
                      );
                      const res = await authService.getSessions(user.email);
                      setSessions(res.data);
                    }}
                  >
                    Invalidate Other Sessions
                  </Button>
                )}
              </Card.Body>
            </Card>
          </Col>
        </Row>
        <style>{`
          .genz-glass {
            backdrop-filter: blur(8px);
            background: rgba(255,255,255,0.85) !important;
          }
        `}</style>
      </Card>
    </div>
  );
};

export default UserProfile;
