import React from "react";
import { Provider, useSelector } from "react-redux";
import {
  BrowserRouter as Router,
  Routes,
  Route,
  Navigate,
  useLocation,
} from "react-router-dom";
import store from "./store/store";
import { AlertSystem } from "./components";
import { ThemeProvider } from "./components/common";
import MainLayout from "./components/layout/MainLayout";
import { routes } from "./routes/routes";
import Login from "./pages/auth/Login";
import Register from "./pages/auth/Register";
import "bootstrap/dist/css/bootstrap.min.css";
import "./styles/globals.css";

// Flatten all routes and children into a single array of route objects with absolute paths
function flattenRoutes(routeList) {
  let flat = [];
  for (const route of routeList) {
    if (route.component) {
      flat.push({ path: route.path, component: route.component });
    }
    if (route.children) {
      flat = flat.concat(flattenRoutes(route.children));
    }
  }
  return flat;
}

function AppContent() {
  const { isAuthenticated, user } = useSelector((state) => state.auth);
  const location = useLocation();

  // If not authenticated, only allow login/register
  if (!isAuthenticated) {
    return (
      <Routes>
        <Route path="/login" element={<Login />} />
        <Route path="/register" element={<Register />} />
        <Route path="*" element={<Navigate to="/login" replace />} />
      </Routes>
    );
  }

  // If authenticated and on /login or /register, redirect to dashboard
  if (
    isAuthenticated &&
    (location.pathname === "/login" || location.pathname === "/register")
  ) {
    return <Navigate to="/dashboard" replace />;
  }

  // Recursively filter routes by permissions
  function filterRoutes(routeList) {
    return routeList
      .filter((route) => {
        if (!route.permissions || route.permissions.length === 0) return true;
        if (!user?.permissions) return false;
        return route.permissions.some((p) => user.permissions.includes(p));
      })
      .map((route) =>
        route.children
          ? { ...route, children: filterRoutes(route.children) }
          : route,
      );
  }

  const allowedRoutes = filterRoutes(routes);
  const flatRoutes = flattenRoutes(allowedRoutes);

  // Authenticated: show main layout and dynamic routes as nested routes
  return (
    <Routes>
      <Route path="/" element={<MainLayout />}>
        {flatRoutes.map((route) => (
          <Route
            key={route.path}
            path={route.path}
            element={<route.component />}
          />
        ))}
        <Route path="*" element={<Navigate to="/dashboard" replace />} />
      </Route>
    </Routes>
  );
}

function App() {
  return (
    <Provider store={store}>
      <ThemeProvider>
        <Router>
          <AlertSystem />
          <AppContent />
        </Router>
      </ThemeProvider>
    </Provider>
  );
}

export default App;
