import React, { useState } from "react";
import {
  Table,
  Button,
  Form,
  Pagination,
  Badge,
  Modal,
  Card,
  Row,
  Col,
  ButtonGroup,
} from "react-bootstrap";
import EditIcon from "@mui/icons-material/Edit";
import DeleteIcon from "@mui/icons-material/Delete";
import VisibilityIcon from "@mui/icons-material/Visibility";
import AddIcon from "@mui/icons-material/Add";
import SearchIcon from "@mui/icons-material/Search";
import FilterListIcon from "@mui/icons-material/FilterList";
import ViewModuleIcon from "@mui/icons-material/ViewModule";
import ViewListIcon from "@mui/icons-material/ViewList";
import {
  StatusBadge,
  Pagination as PaginationComponent,
} from "../../../components/common";

// Dummy data for users
const dummyUsers = [
  {
    id: 1,
    username: "john.doe",
    email: "john.doe@company.com",
    fullName: "John Doe",
    role: "ADMIN",
    status: "ACTIVE",
    lastLogin: "2024-01-15 10:30:00",
    teams: ["Development", "Management"],
    groups: ["Admins"],
    permissions: ["user_management", "fleet_oversight"],
    createdAt: "2023-06-15",
    mfaEnabled: true,
  },
  {
    id: 2,
    username: "jane.smith",
    email: "jane.smith@company.com",
    fullName: "Jane Smith",
    role: "USER",
    status: "ACTIVE",
    lastLogin: "2024-01-14 15:45:00",
    teams: ["Operations", "Support"],
    groups: ["Operators"],
    permissions: ["fleet_oversight"],
    createdAt: "2023-08-20",
    mfaEnabled: false,
  },
  {
    id: 3,
    username: "mike.wilson",
    email: "mike.wilson@company.com",
    fullName: "Mike Wilson",
    role: "USER",
    status: "INACTIVE",
    lastLogin: "2024-01-10 09:15:00",
    teams: ["Development"],
    groups: [],
    permissions: ["fleet_oversight"],
    createdAt: "2023-09-10",
    mfaEnabled: true,
  },
  {
    id: 4,
    username: "sarah.jones",
    email: "sarah.jones@company.com",
    fullName: "Sarah Jones",
    role: "ADMIN",
    status: "ACTIVE",
    lastLogin: "2024-01-15 14:20:00",
    teams: ["Management", "Operations"],
    groups: ["Admins", "Managers"],
    permissions: ["user_management", "team_management", "fleet_oversight"],
    createdAt: "2023-07-05",
    mfaEnabled: true,
  },
  {
    id: 5,
    username: "david.brown",
    email: "david.brown@company.com",
    fullName: "David Brown",
    role: "USER",
    status: "PENDING",
    lastLogin: null,
    teams: ["Support"],
    groups: ["Operators"],
    permissions: ["fleet_oversight"],
    createdAt: "2024-01-12",
    mfaEnabled: false,
  },
];

const availableGroups = ["Admins", "Operators"];

const PAGE_SIZE = 10;

const UserList = () => {
  const [users, setUsers] = useState(dummyUsers);
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("ALL");
  const [roleFilter, setRoleFilter] = useState("ALL");
  const [page, setPage] = useState(1);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [selectedUser, setSelectedUser] = useState(null);
  const [showUserModal, setShowUserModal] = useState(false);
  const [view, setView] = useState("grid"); // 'grid' or 'list'

  const filteredUsers = users.filter((user) => {
    const matchesSearch =
      user.username.toLowerCase().includes(search.toLowerCase()) ||
      user.email.toLowerCase().includes(search.toLowerCase()) ||
      user.fullName.toLowerCase().includes(search.toLowerCase());

    const matchesStatus =
      statusFilter === "ALL" || user.status === statusFilter;
    const matchesRole = roleFilter === "ALL" || user.role === roleFilter;

    return matchesSearch && matchesStatus && matchesRole;
  });

  const totalPages = Math.ceil(filteredUsers.length / PAGE_SIZE);
  const pagedUsers = filteredUsers.slice(
    (page - 1) * PAGE_SIZE,
    page * PAGE_SIZE,
  );

  const handleDelete = (userId) => {
    setUsers(users.filter((user) => user.id !== userId));
    setShowDeleteModal(false);
    setSelectedUser(null);
  };

  const handleStatusChange = (userId, newStatus) => {
    setUsers(
      users.map((user) =>
        user.id === userId ? { ...user, status: newStatus } : user,
      ),
    );
  };

  const getRoleBadge = (role) => {
    const variants = {
      ADMIN: "primary",
      USER: "info",
      MANAGER: "warning",
    };
    return <Badge bg={variants[role] || "secondary"}>{role}</Badge>;
  };

  return (
    <div>
      <div className="d-flex justify-content-between align-items-center mb-4">
        <h2>User Management</h2>
        <div className="d-flex align-items-center gap-2">
          <ButtonGroup>
            <Button
              variant={view === "grid" ? "primary" : "outline-primary"}
              onClick={() => setView("grid")}
              title="Grid View"
            >
              <ViewModuleIcon />
            </Button>
            <Button
              variant={view === "list" ? "primary" : "outline-primary"}
              onClick={() => setView("list")}
              title="List View"
            >
              <ViewListIcon />
            </Button>
          </ButtonGroup>
          <Button variant="primary" onClick={() => setShowUserModal(true)}>
            <AddIcon className="me-2" />
            Add User
          </Button>
        </div>
      </div>

      {/* Filters */}
      <Card className="mb-4">
        <Card.Body>
          <Row>
            <Col md={4}>
              <Form.Group>
                <Form.Label>Search Users</Form.Label>
                <Form.Control
                  type="text"
                  placeholder="Search by name, email, or username..."
                  value={search}
                  onChange={(e) => {
                    setSearch(e.target.value);
                    setPage(1);
                  }}
                />
              </Form.Group>
            </Col>
            <Col md={3}>
              <Form.Group>
                <Form.Label>Status</Form.Label>
                <Form.Select
                  value={statusFilter}
                  onChange={(e) => {
                    setStatusFilter(e.target.value);
                    setPage(1);
                  }}
                >
                  <option value="ALL">All Status</option>
                  <option value="ACTIVE">Active</option>
                  <option value="INACTIVE">Inactive</option>
                  <option value="PENDING">Pending</option>
                  <option value="SUSPENDED">Suspended</option>
                </Form.Select>
              </Form.Group>
            </Col>
            <Col md={3}>
              <Form.Group>
                <Form.Label>Role</Form.Label>
                <Form.Select
                  value={roleFilter}
                  onChange={(e) => {
                    setRoleFilter(e.target.value);
                    setPage(1);
                  }}
                >
                  <option value="ALL">All Roles</option>
                  <option value="ADMIN">Admin</option>
                  <option value="USER">User</option>
                  <option value="MANAGER">Manager</option>
                </Form.Select>
              </Form.Group>
            </Col>
            <Col md={2} className="d-flex align-items-end">
              <Button variant="outline-secondary" className="w-100">
                <FilterListIcon className="me-2" />
                Filters
              </Button>
            </Col>
          </Row>
        </Card.Body>
      </Card>

      {/* Users Table or Grid */}
      {view === "list" ? (
        <Card>
          <Card.Body>
            <Table responsive striped hover>
              <thead>
                <tr>
                  <th>User</th>
                  <th>Role</th>
                  <th>Status</th>
                  <th>Teams</th>
                  <th>Groups</th>
                  <th>Last Login</th>
                  <th>MFA</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {pagedUsers.map((user) => (
                  <tr key={user.id}>
                    <td>
                      <div>
                        <strong>{user.fullName}</strong>
                        <br />
                        <small className="text-muted">{user.email}</small>
                      </div>
                    </td>
                    <td>{getRoleBadge(user.role)}</td>
                    <td>
                      <StatusBadge status={user.status} />
                    </td>
                    <td>
                      {user.teams.map((team) => (
                        <Badge
                          key={team}
                          bg="light"
                          text="dark"
                          className="me-1"
                        >
                          {team}
                        </Badge>
                      ))}
                    </td>
                    <td>
                      {user.groups.map((group) => (
                        <Badge
                          key={group}
                          bg="light"
                          text="dark"
                          className="me-1"
                        >
                          {group}
                        </Badge>
                      ))}
                    </td>
                    <td>
                      {user.lastLogin ? (
                        <small>
                          {new Date(user.lastLogin).toLocaleDateString()}
                        </small>
                      ) : (
                        <small className="text-muted">Never</small>
                      )}
                    </td>
                    <td>
                      <Badge bg={user.mfaEnabled ? "success" : "secondary"}>
                        {user.mfaEnabled ? "Enabled" : "Disabled"}
                      </Badge>
                    </td>
                    <td>
                      <div className="d-flex gap-1">
                        <Button
                          size="sm"
                          variant="outline-primary"
                          title="View"
                        >
                          <VisibilityIcon />
                        </Button>
                        <Button
                          size="sm"
                          variant="outline-warning"
                          title="Edit"
                        >
                          <EditIcon />
                        </Button>
                        <Button
                          size="sm"
                          variant="outline-danger"
                          title="Delete"
                          onClick={() => {
                            setSelectedUser(user);
                            setShowDeleteModal(true);
                          }}
                        >
                          <DeleteIcon />
                        </Button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </Table>
            {/* Pagination */}
            {totalPages > 1 && (
              <PaginationComponent
                currentPage={page}
                totalPages={totalPages}
                onPageChange={setPage}
              />
            )}
          </Card.Body>
        </Card>
      ) : (
        <Row>
          {pagedUsers.map((user) => (
            <Col key={user.id} md={6} lg={4} className="mb-4">
              <Card>
                <Card.Body>
                  <div className="d-flex align-items-center mb-2">
                    <div className="flex-grow-1">
                      <h5 className="mb-1">{user.fullName}</h5>
                      <div className="text-muted" style={{ fontSize: 13 }}>
                        {user.email}
                      </div>
                    </div>
                    <div>{getRoleBadge(user.role)}</div>
                  </div>
                  <div className="mb-2">
                    <strong>Status:</strong>{" "}
                    <StatusBadge status={user.status} />
                  </div>
                  <div className="mb-2">
                    <strong>Teams:</strong>{" "}
                    {user.teams.map((team) => (
                      <Badge key={team} bg="light" text="dark" className="me-1">
                        {team}
                      </Badge>
                    ))}
                  </div>
                  <div className="mb-2">
                    <strong>Groups:</strong>{" "}
                    {user.groups.map((group) => (
                      <Badge key={group} bg="light" text="dark" className="me-1">
                        {group}
                      </Badge>
                    ))}
                  </div>
                  <div className="mb-2">
                    <strong>Last Login:</strong>{" "}
                    {user.lastLogin ? (
                      <small>
                        {new Date(user.lastLogin).toLocaleDateString()}
                      </small>
                    ) : (
                      <small className="text-muted">Never</small>
                    )}
                  </div>
                  <div className="mb-2">
                    <strong>MFA:</strong>{" "}
                    <Badge bg={user.mfaEnabled ? "success" : "secondary"}>
                      {user.mfaEnabled ? "Enabled" : "Disabled"}
                    </Badge>
                  </div>
                  <div className="d-flex gap-1 mt-2">
                    <Button size="sm" variant="outline-primary" title="View">
                      <VisibilityIcon />
                    </Button>
                    <Button size="sm" variant="outline-warning" title="Edit">
                      <EditIcon />
                    </Button>
                    <Button
                      size="sm"
                      variant="outline-danger"
                      title="Delete"
                      onClick={() => {
                        setSelectedUser(user);
                        setShowDeleteModal(true);
                      }}
                    >
                      <DeleteIcon />
                    </Button>
                  </div>
                </Card.Body>
              </Card>
            </Col>
          ))}
          {/* Pagination for grid view */}
          {totalPages > 1 && (
            <PaginationComponent
              currentPage={page}
              totalPages={totalPages}
              onPageChange={setPage}
            />
          )}
        </Row>
      )}

      {/* Delete Confirmation Modal */}
      <Modal
        show={showDeleteModal}
        onHide={() => setShowDeleteModal(false)}
        centered
        backdrop="static"
        style={{ zIndex: 2000 }}
      >
        <Modal.Header closeButton>
          <Modal.Title>Confirm Delete</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          Are you sure you want to delete user{" "}
          <strong>{selectedUser?.fullName}</strong>? This action cannot be
          undone.
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowDeleteModal(false)}>
            Cancel
          </Button>
          <Button
            variant="danger"
            onClick={() => handleDelete(selectedUser?.id)}
          >
            Delete
          </Button>
        </Modal.Footer>
      </Modal>

      {/* Add/Edit User Modal */}
      <Modal
        show={showUserModal}
        onHide={() => setShowUserModal(false)}
        size="lg"
        centered
        backdrop="static"
        style={{ zIndex: 2000 }}
      >
        <Modal.Header closeButton>
          <Modal.Title>Add New User</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Form>
            <Row>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>Full Name</Form.Label>
                  <Form.Control type="text" placeholder="Enter full name" />
                </Form.Group>
              </Col>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>Username</Form.Label>
                  <Form.Control type="text" placeholder="Enter username" />
                </Form.Group>
              </Col>
            </Row>
            <Row>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>Email</Form.Label>
                  <Form.Control type="email" placeholder="Enter email" />
                </Form.Group>
              </Col>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>Role</Form.Label>
                  <Form.Select>
                    <option value="USER">User</option>
                    <option value="ADMIN">Admin</option>
                    <option value="MANAGER">Manager</option>
                  </Form.Select>
                </Form.Group>
              </Col>
            </Row>
            <Row>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>Status</Form.Label>
                  <Form.Select>
                    <option value="ACTIVE">Active</option>
                    <option value="INACTIVE">Inactive</option>
                    <option value="PENDING">Pending</option>
                  </Form.Select>
                </Form.Group>
              </Col>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>Teams</Form.Label>
                  <Form.Select multiple>
                    <option value="Development">Development</option>
                    <option value="Operations">Operations</option>
                    <option value="Support">Support</option>
                    <option value="Management">Management</option>
                  </Form.Select>
                </Form.Group>
              </Col>
            </Row>
            <Row>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>Groups</Form.Label>
                  <Form.Select multiple>
                    {availableGroups.map((group) => (
                      <option key={group} value={group}>
                        {group}
                      </option>
                    ))}
                  </Form.Select>
                </Form.Group>
              </Col>
            </Row>
          </Form>
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowUserModal(false)}>
            Cancel
          </Button>
          <Button variant="primary">Save User</Button>
        </Modal.Footer>
      </Modal>
    </div>
  );
};

export default UserList;
