import React from "react";
import { Badge } from "react-bootstrap";

const statusMap = {
  ACTIVE: "success",
  INACTIVE: "secondary",
  PENDING: "warning",
  SUSPENDED: "danger",
  DEFAULT: "secondary",
};

const StatusBadge = ({ status, children }) => (
  <Badge bg={statusMap[status] || statusMap.DEFAULT}>
    {children || status}
  </Badge>
);

export default StatusBadge;
