import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  realTimeLocations: {}, // { [vehicleId]: VehicleLocation }
  historicalData: {},    // { [vehicleId]: HistoricalTrackingData }
  connectionStatus: 'disconnected', // 'connected' | 'disconnected'
  offlineBuffer: [],     // Array of LocationData
};

const trackingSlice = createSlice({
  name: 'tracking',
  initialState,
  reducers: {
    updateRealTimeLocation: (state, action) => {
      const { vehicleId, location } = action.payload;
      state.realTimeLocations[vehicleId] = location;
    },
    setHistoricalData: (state, action) => {
      const { vehicleId, data } = action.payload;
      state.historicalData[vehicleId] = data;
    },
    setConnectionStatus: (state, action) => {
      state.connectionStatus = action.payload;
    },
    addToOfflineBuffer: (state, action) => {
      state.offlineBuffer.push(action.payload);
    },
    clearOfflineBuffer: (state) => {
      state.offlineBuffer = [];
    },
  },
});

export const {
  updateRealTimeLocation,
  setHistoricalData,
  setConnectionStatus,
  addToOfflineBuffer,
  clearOfflineBuffer,
} = trackingSlice.actions;

export default trackingSlice.reducer; 