// MOCK VEHICLE SERVICE - CRUD operations

let MOCK_VEHICLES = [
  {
    vehicleId: "veh-1",
    registrationNumber: "ABC123",
    vin: "VIN123",
    make: "Toyota",
    model: "Corolla",
    year: 2020,
    status: "ACTIVE",
    category: { categoryName: "Car" },
  },
  {
    vehicleId: "veh-2",
    registrationNumber: "XYZ789",
    vin: "VIN456",
    make: "Ford",
    model: "F-150",
    year: 2019,
    status: "MAINTENANCE",
    category: { categoryName: "Truck" },
  },
  // ... more vehicles for pagination demo
  ...Array.from({ length: 28 }, (_, i) => ({
    vehicleId: `veh-${i + 3}`,
    registrationNumber: `REG${100 + i}`,
    vin: `VIN${1000 + i}`,
    make: ["Toyota", "Ford", "Honda", "Chevy", "Nissan"][i % 5],
    model: ["Corolla", "F-150", "Civic", "Silverado", "Altima"][i % 5],
    year: 2015 + (i % 8),
    status: ["ACTIVE", "MAINTENANCE", "INACTIVE"][i % 3],
    category: { categoryName: ["Car", "Truck", "SUV"][i % 3] },
  })),
];

export const getVehicles = () => {
  return Promise.resolve({ data: MOCK_VEHICLES });
};

export const addVehicle = (vehicle) => {
  MOCK_VEHICLES.push(vehicle);
  return Promise.resolve({ data: vehicle });
};

export const updateVehicle = (vehicle) => {
  const idx = MOCK_VEHICLES.findIndex(v => v.vehicleId === vehicle.vehicleId);
  if (idx !== -1) {
    MOCK_VEHICLES[idx] = vehicle;
    return Promise.resolve({ data: vehicle });
  }
  return Promise.reject({ response: { data: { message: "Vehicle not found" } } });
};

export const removeVehicle = (vehicleId) => {
  MOCK_VEHICLES = MOCK_VEHICLES.filter(v => v.vehicleId !== vehicleId);
  return Promise.resolve({ data: vehicleId });
};

// Mock assignments
let MOCK_ASSIGNMENTS = [
  // { assignmentId, vehicleId, driverId, routeId, assignedDate, unassignedDate, status }
];

export const getVehicleAssignments = (vehicleId) => {
  if (vehicleId) {
    return Promise.resolve({
      data: MOCK_ASSIGNMENTS.filter((a) => a.vehicleId === vehicleId),
    });
  }
  return Promise.resolve({ data: MOCK_ASSIGNMENTS });
};

export const assignVehicle = (assignment) => {
  const newAssignment = {
    ...assignment,
    assignmentId: `assign-${Date.now()}`,
    assignedDate: new Date().toISOString(),
    status: "ASSIGNED",
  };
  MOCK_ASSIGNMENTS.push(newAssignment);
  return Promise.resolve({ data: newAssignment });
};

export const unassignVehicle = (assignmentId) => {
  const idx = MOCK_ASSIGNMENTS.findIndex((a) => a.assignmentId === assignmentId);
  if (idx !== -1) {
    MOCK_ASSIGNMENTS[idx].unassignedDate = new Date().toISOString();
    MOCK_ASSIGNMENTS[idx].status = "UNASSIGNED";
    return Promise.resolve({ data: MOCK_ASSIGNMENTS[idx] });
  }
  return Promise.reject({ response: { data: { message: "Assignment not found" } } });
};

// Mock vehicle audit logs
let MOCK_VEHICLE_AUDIT_LOGS = [
  // { id, vehicleId, userId, action, details, timestamp }
];

export const getVehicleAuditLogs = (vehicleId) => {
  if (vehicleId) {
    return Promise.resolve({
      data: MOCK_VEHICLE_AUDIT_LOGS.filter((log) => log.vehicleId === vehicleId),
    });
  }
  return Promise.resolve({ data: MOCK_VEHICLE_AUDIT_LOGS });
};

export const addVehicleAuditLog = (vehicleId, userId, action, details = {}) => {
  const newLog = {
    id: MOCK_VEHICLE_AUDIT_LOGS.length + 1,
    vehicleId,
    userId,
    action,
    details,
    timestamp: Date.now(),
  };
  MOCK_VEHICLE_AUDIT_LOGS.push(newLog);
  return Promise.resolve({ data: newLog });
}; 