import React, { useState } from "react";
import { useForm } from "react-hook-form";
import { yupResolver } from "@hookform/resolvers/yup";
import * as yup from "yup";
import { useAuth } from "../../hooks/useAuth";
import { useAlert } from "../../hooks/useAlert";
import { Button, Form, Card, Spinner, Alert } from "react-bootstrap";
import MFAVerify from "./MFAVerify";

const schema = yup.object().shape({
  email: yup.string().email("Invalid email").required("Email is required"),
  password: yup
    .string()
    .min(6, "Password must be at least 6 characters")
    .required("Password is required"),
  captcha: yup.string().when("showCaptcha", {
    is: true,
    then: () => yup.string().required("CAPTCHA is required"),
    otherwise: () => yup.string().notRequired(),
  }),
});

// Simple mock CAPTCHA generator
function generateCaptcha() {
  const a = Math.floor(Math.random() * 10) + 1;
  const b = Math.floor(Math.random() * 10) + 1;
  return {
    question: `What is ${a} + ${b}?`,
    answer: (a + b).toString(),
  };
}

const Login = () => {
  const { login, loading, error, clearAuthError } = useAuth();
  const { showError, showSuccess } = useAlert();
  const [failedAttempts, setFailedAttempts] = useState(0);
  const [lockout, setLockout] = useState(false);
  const [captcha, setCaptcha] = useState(generateCaptcha());
  const [showCaptcha, setShowCaptcha] = useState(false);
  const [rememberMe, setRememberMe] = useState(false);
  const [pendingMFA, setPendingMFA] = useState(false);
  const [mfaUser, setMfaUser] = useState(null);
  const {
    register,
    handleSubmit,
    formState: { errors },
    setValue,
    reset,
  } = useForm({
    resolver: yupResolver(schema),
  });

  const onSubmit = async (data) => {
    if (showCaptcha && data.captcha !== captcha.answer) {
      showError("CAPTCHA incorrect");
      setCaptcha(generateCaptcha());
      setValue("captcha", "");
      return;
    }
    // Step 1: Try login, but do not complete if MFA is enabled
    const resultAction = await login(data.email, data.password, rememberMe);
    if (resultAction.error) {
      showError(resultAction.error.message || "Login failed");
      if (
        resultAction.error.message &&
        resultAction.error.message.includes("locked")
      ) {
        setLockout(true);
      }
      setFailedAttempts((prev) => {
        const next = prev + 1;
        if (next >= 3) setShowCaptcha(true);
        return next;
      });
      setCaptcha(generateCaptcha());
      setValue("captcha", "");
    } else {
      // If MFA is enabled, show MFA verification step
      if (resultAction.payload?.user?.mfa?.enabled) {
        setPendingMFA(true);
        setMfaUser(resultAction.payload.user);
        return;
      }
      showSuccess("Login successful!");
      setFailedAttempts(0);
      setShowCaptcha(false);
      setLockout(false);
      reset();
    }
  };

  const handleMFASuccess = () => {
    showSuccess("Login successful!");
    setPendingMFA(false);
    setMfaUser(null);
    setFailedAttempts(0);
    setShowCaptcha(false);
    setLockout(false);
    reset();
  };

  React.useEffect(() => {
    if (error) showError(error);
    return () => clearAuthError();
    // eslint-disable-next-line
  }, [error]);

  if (pendingMFA && mfaUser) {
    return <MFAVerify user={mfaUser} onSuccess={handleMFASuccess} />;
  }

  return (
    <div className="d-flex justify-content-center align-items-center min-vh-100 bg-light">
      <Card style={{ width: 350 }}>
        <Card.Body>
          <h3 className="mb-4 text-center">Login</h3>
          {lockout && (
            <Alert variant="danger">
              Your account is locked due to too many failed login attempts.
              Please try again after 15 minutes.
            </Alert>
          )}
          <Form onSubmit={handleSubmit(onSubmit)}>
            <Form.Group className="mb-3">
              <Form.Label>Email</Form.Label>
              <Form.Control
                type="email"
                {...register("email")}
                isInvalid={!!errors.email}
                autoComplete="username"
              />
              <Form.Control.Feedback type="invalid">
                {errors.email?.message}
              </Form.Control.Feedback>
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Password</Form.Label>
              <Form.Control
                type="password"
                {...register("password")}
                isInvalid={!!errors.password}
                autoComplete="current-password"
              />
              <Form.Control.Feedback type="invalid">
                {errors.password?.message}
              </Form.Control.Feedback>
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Check
                type="checkbox"
                label="Remember Me"
                checked={rememberMe}
                onChange={(e) => setRememberMe(e.target.checked)}
              />
            </Form.Group>
            {showCaptcha && (
              <Form.Group className="mb-3">
                <Form.Label>CAPTCHA: {captcha.question}</Form.Label>
                <Form.Control
                  type="text"
                  {...register("captcha")}
                  isInvalid={!!errors.captcha}
                  autoComplete="off"
                />
                <Form.Control.Feedback type="invalid">
                  {errors.captcha?.message}
                </Form.Control.Feedback>
              </Form.Group>
            )}
            <Button
              type="submit"
              variant="primary"
              className="w-100"
              disabled={loading || lockout}
            >
              {loading ? <Spinner animation="border" size="sm" /> : "Login"}
            </Button>
          </Form>
        </Card.Body>
      </Card>
    </div>
  );
};

export default Login;
