import { useState, useEffect } from 'react';
import { useDispatch } from 'react-redux';
import { fetchHistoricalTracking } from '../services/tracking.service';
import { setHistoricalData } from '../slices/trackingSlice';

export const useHistoricalTracking = (vehicleId, dateRange) => {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const dispatch = useDispatch();

  useEffect(() => {
    if (!vehicleId || !dateRange?.start || !dateRange?.end) return;

    const fetchData = async () => {
      setLoading(true);
      setError(null);
      
      try {
        const response = await fetchHistoricalTracking(
          vehicleId, 
          dateRange.start.toISOString(), 
          dateRange.end.toISOString()
        );
        
        dispatch(setHistoricalData({ 
          vehicleId, 
          data: response.data 
        }));
      } catch (err) {
        setError(err.message || 'Failed to fetch historical data');
        console.error('Historical tracking error:', err);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [vehicleId, dateRange?.start, dateRange?.end, dispatch]);

  return { loading, error };
}; 