import React from "react";
import { Card, Button, ListGroup } from "react-bootstrap";
import TripMap from "./TripMap";

const RoutePlanner = ({ route, stops, onRouteChange, onStopsChange, readOnly = false }) => {
  const handleOptimize = () => {
    // Dummy optimization: reverse stops order
    const optimizedStops = [...(stops || [])].reverse();
    onRouteChange && onRouteChange({ ...route, optimized: true });
    onStopsChange && onStopsChange(optimizedStops);
  };

  const handleAddStop = () => {
    const newStop = { name: `Stop #${(stops?.length || 0) + 1}`, address: "New Address" };
    onStopsChange && onStopsChange([...(stops || []), newStop]);
  };

  return (
    <Card>
      <Card.Header>
        <h5 className="mb-0">Route Planning</h5>
      </Card.Header>
      <Card.Body>
        <h6>Stops</h6>
        {stops && stops.length ? (
          <ListGroup className="mb-3">
            {stops.map((stop, idx) => (
              <ListGroup.Item key={idx}>
                <strong>{stop.name}</strong>
                <br />
                <span className="text-muted">{stop.address}</span>
              </ListGroup.Item>
            ))}
          </ListGroup>
        ) : (
          <div className="mb-3 text-muted">No stops added</div>
        )}
        {!readOnly && (
          <Button variant="outline-primary" className="me-2" onClick={handleAddStop}>
            + Add Stop
          </Button>
        )}
        <hr />
        <h6>Route Optimization</h6>
        <div className="mb-2">
          <span>Optimized: </span>
          <strong>{route?.optimized ? "Yes" : "No"}</strong>
        </div>
        {!readOnly && (
          <Button variant="success" onClick={handleOptimize}>
            Optimize Route
          </Button>
        )}
        <div className="mt-4">
          <TripMap route={route} stops={stops} readOnly={readOnly} />
        </div>
      </Card.Body>
    </Card>
  );
};

export default RoutePlanner; 