  Dashboard: <SpaceDashboardIcon fontSize="medium" />, // modern dashboard
  "Audit Logs": <ReceiptLongIcon fontSize="medium" />, // logs
  Permissions: <AdminPanelSettingsIcon fontSize="medium" />, // admin panel
  "User Management": <ManageAccountsIcon fontSize="medium" />, // user mgmt
  "Users List": <PeopleIcon fontSize="medium" />,
  "User Roles": <SupervisorAccountIcon fontSize="medium" />,
  "User Permissions": <LockPersonIcon fontSize="medium" />,
  "User Activity": <HistoryIcon fontSize="medium" />,
  "Team Management": <GroupsIcon fontSize="medium" />,
  "Teams List": <Groups2Icon fontSize="medium" />,
  "Team Members": <GroupAddIcon fontSize="medium" />,
  "Team Assignments": <AssignmentIndIcon fontSize="medium" />,
  "Team Permissions": <VerifiedUserIcon fontSize="medium" />,
  "Group Management": <Diversity3Icon fontSize="medium" />,
  "Groups List": <Diversity3Icon fontSize="medium" />,
  "Client Management": <BusinessIcon fontSize="medium" />,
  "Clients List": <BusinessIcon fontSize="medium" />,
  "Driver Management": <EmojiTransportationIcon fontSize="medium" />,
  "Driver List": <DriveEtaIcon fontSize="medium" />,
