const getIcon = (label) =>
  iconMap[label] || <DashboardIcon fontSize="medium" />;

function filterRoutes(routeList, permissions) {
  return routeList
    .filter((route) => {
      if (route.showInMenu === false) return false;
      if (!route.permissions || route.permissions.length === 0) return true;
      if (!permissions) return false;
      return route.permissions.some((p) => permissions.includes(p));
    })
    .map((route) =>
      route.children
        ? { ...route, children: filterRoutes(route.children, permissions) }
        : route,
    );
}

const SIDEBAR_COLLAPSED_WIDTH = 72;
const SIDEBAR_EXPANDED_WIDTH = 280;
const SIDEBAR_BG_DARK = "#1F2937";
const SIDEBAR_BG_LIGHT = "#fff";
const ACCENT_COLOR = "#764ba2";
const ACTIVE_BG = "rgba(255,255,255,0.18)";
const HOVER_BG = "rgba(255,255,255,0.10)";
const BADGE_BG = "#f093fb";
const STATUS_GREEN = "#22c55e";

const isMobile = () => window.innerWidth < 768;

const mockBadgeCounts = {
  logs: 3,
  reports: 2,
  maintenance: 1,
};
const mockProgress = 0.6; // 60% for demo
const mockStatus = "All systems operational";

const Sidebar = ({ role, permissions, language = "en", onLanguageChange }) => {
  const { currentClient, clientPermissions } = useSelector((state) => state.auth);
  const location = useLocation();
  const [expandedMenu, setExpandedMenu] = useState(null);
  // Use clientPermissions if in client context, else use passed permissions
  const effectivePermissions = currentClient ? clientPermissions : permissions;
  const allowedRoutes = filterRoutes(routes, effectivePermissions);
  const [collapsed, setCollapsed] = useState(
    localStorage.getItem("adminSidebarCollapsed") === "true" || false,
  );
  const [hovered, setHovered] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);
  const sidebarRef = useRef();
  const overlayRef = useRef();

  const isMobileDevice = isMobile();

  // Collapse/expand logic
  const handleToggle = () => {
    setCollapsed((prev) => {
      localStorage.setItem("adminSidebarCollapsed", !prev);
      return !prev;
    });
  };

  // Collapse sidebar on navigation
  const handleNavClick = () => {
    setCollapsed(true);
    localStorage.setItem("adminSidebarCollapsed", true);
  };

  // Mobile overlay: auto-collapse on resize
  useEffect(() => {
    const onResize = () => {
      if (isMobile()) setMobileOpen(false);
    };
    window.addEventListener("resize", onResize);
    return () => window.removeEventListener("resize", onResize);
  }, []);

  // Dismiss mobile overlay on outside click or Esc
  useEffect(() => {
    if (!mobileOpen) return;
    const handleClick = (e) => {
      if (overlayRef.current && e.target === overlayRef.current)
        setMobileOpen(false);
    };
    const handleEsc = (e) => {
      if (e.key === "Escape") setMobileOpen(false);
    };
    document.addEventListener("mousedown", handleClick);
    document.addEventListener("keydown", handleEsc);
    return () => {
      document.removeEventListener("mousedown", handleClick);
      document.removeEventListener("keydown", handleEsc);
    };
  }, [mobileOpen]);

  // Accessibility: skip to content
  const skipToContent = () => {
    const main = document.querySelector("main");
    if (main) main.focus();
  };

  // Sidebar styles (GenZ look)
  const sidebarStyle = {
    position: isMobile() && mobileOpen ? "fixed" : "relative",
    left: 0,
    top: 0,
    height: isMobile() && mobileOpen ? "100vh" : "100%",
    width:
      collapsed && !hovered ? SIDEBAR_COLLAPSED_WIDTH : SIDEBAR_EXPANDED_WIDTH,
    background: "var(--primary)",
    color: "var(--neutral-light)",
    boxShadow: "2px 0 16px rgba(0,0,0,0.10)",
    zIndex: 1100,
    transition: "width 0.2s ease-in-out, transform 0.2s",
    overflowX: "hidden",
    display: "flex",
    flexDirection: "column",
    transform:
      isMobile() && !mobileOpen ? "translateX(-100%)" : "translateX(0)",
    backdropFilter: "blur(8px)",
    backgroundBlendMode: "overlay",
    borderRight: "1.5px solid rgba(255,255,255,0.12)",
  };

  // Overlay for mobile
  const overlay =
    isMobile() && mobileOpen ? (
      <div
        ref={overlayRef}
        style={{
          position: "fixed",
          top: 0,
          left: 0,
          width: "100vw",
          height: "100vh",
          background: "rgba(51,51,51,0.5)",
          zIndex: 1099,
        }}
        aria-label="Sidebar overlay"
      />
    ) : null;

  const renderMenu = (items, depth = 0) => (
    <ul style={{ listStyle: "none", paddingLeft: depth * 16, margin: 0 }}>
      {items.map((item) => {
        const isActive = location.pathname === item.path;
        const hasChildren = item.children && item.children.length > 0;
        const isExpanded = expandedMenu === item.path;
        // Show labels only if not collapsed or hovered
        const showLabels = !(collapsed && !hovered);
        return (
          <li
            key={item.path}
            className={clsx("sidebar-item", { active: isActive })}
          >
            {hasChildren ? (
              <div
                className="sidebar-link sidebar-parent"
                tabIndex={0}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: showLabels ? 16 : 0,
                  padding: showLabels ? "12px 20px" : "12px 0",
                  borderRadius: 12,
                  color: "var(--neutral-light)",
                  fontWeight: 600,
                  fontSize: 16,
                  minHeight: 48,
                  marginBottom: 2,
                  cursor: "pointer",
                  outline: "none",
                  background: "none",
                  justifyContent: showLabels ? "flex-start" : "center",
                }}
                aria-haspopup="true"
                aria-expanded={isExpanded}
                onClick={() => setExpandedMenu(isExpanded ? null : item.path)}
                onKeyDown={(e) => {
                  if (e.key === "Enter" || e.key === " ")
                    setExpandedMenu(isExpanded ? null : item.path);
                }}
              >
                <span
                  style={{
                    minWidth: 24,
                    display: "flex",
                    justifyContent: "center",
                  }}
                >
                  {getIcon(item.label)}
                </span>
                {showLabels && <span>{item.label}</span>}
                {showLabels && (
                  <span style={{ marginLeft: "auto" }}>
                    {isExpanded ? "▲" : "▼"}
                  </span>
                )}
              </div>
            ) : (
              <NavLink
                to={item.path}
                className={({ isActive }) =>
                  clsx("sidebar-link", {
                    active: isActive,
                    collapsed: collapsed && !hovered,
                  })
                }
                tabIndex={0}
                aria-current={isActive ? "page" : undefined}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: showLabels ? 16 : 0,
                  padding: showLabels ? "12px 20px" : "12px 0",
                  borderRadius: 12,
                  color: "var(--neutral-light)",
                  background: isActive ? "rgba(255,255,255,0.18)" : "none",
                  fontWeight: isActive ? 700 : 500,
                  fontSize: 16,
                  outline: "none",
                  minHeight: 48,
                  marginBottom: 2,
                  transition: "background 0.2s, color 0.2s",
                  position: "relative",
                  boxShadow: isActive
                    ? "0 2px 12px rgba(118,75,162,0.10)"
                    : "none",
                  justifyContent: showLabels ? "flex-start" : "center",
                }}
              >
                <span
                  style={{
                    minWidth: 24,
                    display: "flex",
                    justifyContent: "center",
                  }}
                >
                  {getIcon(item.label)}
                </span>
                {showLabels && <span>{item.label}</span>}
              </NavLink>
            )}
            {hasChildren && isExpanded && renderMenu(item.children, depth + 1)}
          </li>
        );
      })}
    </ul>
  );

  return (
    <>
      {/* Mobile menu icon (top left) */}
      {isMobileDevice && !mobileOpen && (
        <button
          aria-label="Open sidebar"
          onClick={() => setMobileOpen(true)}
          style={{
            position: "fixed",
            top: 16,
            left: 16,
            zIndex: 1202,
            background: "var(--primary)",
            color: "var(--neutral-light)",
            border: "none",
            borderRadius: 8,
            padding: 8,
            boxShadow: "0 2px 8px rgba(0,0,0,0.10)",
            fontSize: 28,
            cursor: "pointer",
          }}
        >
          <MenuIcon />
        </button>
      )}
      {overlay}
      {/* Sidebar nav: only render on desktop or if mobileOpen is true */}
      {(!isMobileDevice || mobileOpen) && (
        <nav
          ref={sidebarRef}
          className={clsx("admin-sidebar", {
            collapsed: collapsed && !hovered,
            [`theme-genz`]: true,
          })}
          style={sidebarStyle}
          aria-label="Main navigation"
          role="navigation"
          onMouseEnter={() => setHovered(true)}
          onMouseLeave={() => setHovered(false)}
        >
          <a
            href="#main-content"
            className="visually-hidden-focusable"
            tabIndex={0}
            onClick={skipToContent}
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              zIndex: 1201,
              background: "var(--accent)",
              color: "var(--neutral-light)",
              padding: 4,
              borderRadius: 4,
              outline: "none",
            }}
          >
            Skip to main content
          </a>
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              height: "100%",
              minHeight: 0,
              flex: 1,
            }}
          >
            {/* Menu items take all available space above the toggle */}
            <div
              style={{
                flex: 1,
                minHeight: 0,
                overflowY: "auto",
                paddingTop: 8,
              }}
            >
              {renderMenu(allowedRoutes)}
              {/* Custom Switch Client link for users */}
              {role === 'user' && (
                <NavLink
                  to="/user/switch-client"
                  className={({ isActive }) =>
                    clsx("sidebar-link", { active: isActive, collapsed: collapsed && !hovered })
                  }
                  tabIndex={0}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: collapsed && !hovered ? 0 : 16,
                    padding: collapsed && !hovered ? "12px 0" : "12px 20px",
                    borderRadius: 12,
                    color: "var(--neutral-light)",
                    background: "none",
                    fontWeight: 500,
                    fontSize: 16,
                    outline: "none",
                    minHeight: 48,
                    marginBottom: 2,
                    transition: "background 0.2s, color 0.2s",
                    position: "relative",
                    justifyContent: collapsed && !hovered ? "center" : "flex-start",
                  }}
                >
                  <span style={{ minWidth: 24, display: "flex", justifyContent: "center" }}>
                    <SwapHorizIcon fontSize="medium" />
                  </span>
                  {!(collapsed && !hovered) && <span>Switch Client</span>}
                </NavLink>
              )}
            </div>
            {/* Sidebar toggle button at the very bottom (desktop only) */}
            {!isMobileDevice && (
              <div
                style={{
                  width: "100%",
                  display: "flex",
                  justifyContent: collapsed && !hovered ? "center" : "flex-end",
                  alignItems: "center",
                  padding: collapsed && !hovered ? "8px 0" : "8px 16px",
                  borderTop: "1.5px solid rgba(255,255,255,0.12)",
                  marginTop: 0,
                  minHeight: 56,
                }}
              >
                <button
                  className="sidebar-toggle"
                  aria-label={collapsed ? "Expand sidebar" : "Collapse sidebar"}
                  onClick={handleToggle}
                  style={{
                    background: "none",
                    border: "none",
                    color: "var(--neutral-light)",
                    fontSize: 28,
                    cursor: "pointer",
                    outline: "none",
                    marginLeft: 8,
                    transition: "transform 0.3s",
                    transform:
                      collapsed && !hovered ? "rotate(0deg)" : "rotate(180deg)",
                  }}
                >
                  <KeyboardBackspaceIcon />
                </button>
              </div>
            )}
          </div>
        </nav>
      )}
    </>
  );
};

export default Sidebar;
