import React, { useEffect, useRef, useState } from "react";
import { Card, Button } from "react-bootstrap";
import TripMap from "./TripMap";
import { MapContainer as LeafletMap, TileLayer, Polyline, Marker } from "react-leaflet";
import L from 'leaflet';

const GUJARAT_CENTER = [23.0225, 72.5714];
const DEMO_PATH = [
  [23.0225, 72.5714], // Ahmedabad
  [22.3072, 73.1812], // Vadodara
  [21.1702, 72.8311], // Surat
  [23.2156, 72.6369], // Gandhinagar
  [23.0225, 72.5714], // Ahmedabad (loop)
];
const vehicleIcon = new L.Icon({
  iconUrl: 'https://cdn-icons-png.flaticon.com/512/936/936810.png',
  iconSize: [32, 32],
  iconAnchor: [25, 25],
});

function DemoVehicleMarker({ progress }) {
  // Interpolate between points for smooth animation
  const seg = Math.floor(progress);
  const nextSeg = (seg + 1) % DEMO_PATH.length;
  const frac = progress - seg;
  const start = DEMO_PATH[seg];
  const end = DEMO_PATH[nextSeg];
  const lat = start[0] + (end[0] - start[0]) * frac;
  const lng = start[1] + (end[1] - start[1]) * frac;
  return <Marker position={{ lat, lng }} icon={vehicleIcon} />;
}

const RoutePlayback = ({ route, playbackData = [], onPlay, stops = [], demoMode = false }) => {
  // Demo: show playback points as a path and a moving dot
  const [demoProgress, setDemoProgress] = useState(0);
  const demoInterval = useRef(null);
  useEffect(() => {
    if (!demoMode) return;
    demoInterval.current = setInterval(() => {
      setDemoProgress((p) => (p + 0.01) % (DEMO_PATH.length - 1));
    }, 100);
    return () => clearInterval(demoInterval.current);
  }, [demoMode]);
  const currentIdx = playbackData.length > 0 ? playbackData.length - 1 : null;
  return (
    <Card>
      <Card.Header>
        <h5 className="mb-0">Route Playback</h5>
      </Card.Header>
      <Card.Body>
        <div className="mb-2">
          <strong>Route:</strong> {route?.name || "-"}
        </div>
        <div className="mb-2">
          <strong>Playback Points:</strong> {playbackData.length}
        </div>
        <Button variant="primary" onClick={onPlay} disabled={!onPlay} className="mb-3">
          Play
        </Button>
        <div className="border rounded p-3 text-center text-muted" style={{ minHeight: 180, background: '#f8fafc' }}>
          {demoMode ? (
            <LeafletMap center={GUJARAT_CENTER} zoom={8} style={{ height: "160px", width: "100%" }} scrollWheelZoom={false} dragging={true}>
              <TileLayer
                url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
                attribution="&copy; OpenStreetMap contributors"
              />
              <Polyline positions={DEMO_PATH} color="#3b82f6" weight={4} />
              <DemoVehicleMarker progress={demoProgress} />
            </LeafletMap>
          ) : (
            <svg width="100%" height="60" viewBox="0 0 400 60">
              {/* Path */}
              {playbackData.length > 1 && (
                <polyline
                  points={playbackData.map((p, i) => `${40 + i * 40},30`).join(' ')}
                  fill="none"
                  stroke="#6366f1"
                  strokeWidth="4"
                />
              )}
              {/* Playback points */}
              {playbackData.map((p, i) => (
                <circle key={i} cx={40 + i * 40} cy={30} r={7} fill="#f59e42" stroke="#fff" strokeWidth="2" />
              ))}
              {/* Current point */}
              {currentIdx !== null && (
                <circle cx={40 + currentIdx * 40} cy={30} r={10} fill="#22c55e" stroke="#fff" strokeWidth="3" />
              )}
            </svg>
          )}
        </div>
        <div className="mt-3">
          <TripMap route={route} stops={stops} playbackData={playbackData} demoMode={demoMode} />
        </div>
      </Card.Body>
    </Card>
  );
};

export default RoutePlayback; 