import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import { authService } from "../services";

export const loginUser = createAsyncThunk(
  "auth/login",
  async ({ email, password, rememberMe }, { rejectWithValue }) => {
    try {
      const response = await authService.login(email, password);
      // Store token with expiry if rememberMe is true
      if (rememberMe) {
        const expiry = Date.now() + 30 * 24 * 60 * 60 * 1000; // 30 days
        localStorage.setItem("rememberMe", "true");
        localStorage.setItem("token_expiry", expiry);
      } else {
        localStorage.removeItem("rememberMe");
        localStorage.removeItem("token_expiry");
      }
      return response.data;
    } catch (error) {
      return rejectWithValue(error.response?.data?.message || "Login failed");
    }
  },
);

const authSlice = createSlice({
  name: "auth",
  initialState: {
    user: null,
    token: null,
    isAuthenticated: false,
    loading: false,
    error: null,
    currentClient: null, // Added for client switching
    clientPermissions: [], // Permissions for the selected client
  },
  reducers: {
    logout: (state) => {
      state.user = null;
      state.token = null;
      state.isAuthenticated = false;
      state.currentClient = null;
      state.clientPermissions = [];
      authService.logout();
      localStorage.removeItem("rememberMe");
      localStorage.removeItem("token_expiry");
    },
    clearError: (state) => {
      state.error = null;
    },
    switchClient: (state, action) => {
      // action.payload: { client, permissions }
      state.currentClient = action.payload.client;
      state.clientPermissions = action.payload.permissions;
    },
    clearClient: (state) => {
      state.currentClient = null;
      state.clientPermissions = [];
    },
  },
  extraReducers: (builder) => {
    builder
      .addCase(loginUser.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(loginUser.fulfilled, (state, action) => {
        state.loading = false;
        state.user = action.payload.user;
        state.token = action.payload.token;
        state.isAuthenticated = true;
      })
      .addCase(loginUser.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload;
      });
  },
});

export const { logout, clearError, switchClient, clearClient } = authSlice.actions;
export default authSlice.reducer;
