import React, { useState } from "react";
import { Table, Button, Form, Badge, Row, Col } from "react-bootstrap";

const statusColors = {
  LIVE: "success",
  SCHEDULED: "primary",
  COMPLETED: "secondary",
  CANCELLED: "danger",
};

const TripList = ({ trips, onEdit, onView, onSplit, onAutoCreate }) => {
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("ALL");

  const filteredTrips = trips.filter((trip) => {
    const matchesSearch =
      trip.title.toLowerCase().includes(search.toLowerCase()) ||
      trip.description.toLowerCase().includes(search.toLowerCase()) ||
      trip.vehicle?.name.toLowerCase().includes(search.toLowerCase()) ||
      trip.driver?.name.toLowerCase().includes(search.toLowerCase());
    const matchesStatus =
      statusFilter === "ALL" || trip.status === statusFilter;
    return matchesSearch && matchesStatus;
  });

  return (
    <div>
      <Row className="mb-3">
        <Col md={8}>
          <Form.Control
            type="text"
            placeholder="Search by title, description, vehicle, or driver..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </Col>
        <Col md={4}>
          <Form.Select
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
          >
            <option value="ALL">All Status</option>
            <option value="LIVE">Live</option>
            <option value="SCHEDULED">Scheduled</option>
            <option value="COMPLETED">Completed</option>
            <option value="CANCELLED">Cancelled</option>
          </Form.Select>
        </Col>
      </Row>
      <Table responsive striped hover>
        <thead>
          <tr>
            <th>Title</th>
            <th>Type</th>
            <th>Status</th>
            <th>Vehicle</th>
            <th>Driver</th>
            <th>Source</th>
            <th>Destination</th>
            <th>Tags</th>
            <th>Sub-Trips</th>
            <th>Analytics</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {filteredTrips.length === 0 ? (
            <tr>
              <td colSpan={11} className="text-center text-muted">
                No trips found.
              </td>
            </tr>
          ) : (
            filteredTrips.map((trip) => (
              <tr key={trip.id}>
                <td>{trip.title}</td>
                <td>{trip.instant ? 'Quick' : trip.preset ? 'Template' : 'Standard'}</td>
                <td>
                  <Badge bg={statusColors[trip.status] || "secondary"}>
                    {trip.status}
                  </Badge>
                </td>
                <td>{trip.vehicle?.name || "-"}</td>
                <td>{trip.driver?.name || "-"}</td>
                <td>{trip.source?.name || "-"}</td>
                <td>{trip.destination?.name || "-"}</td>
                <td>
                  {trip.tags?.map((tag) => (
                    <Badge key={tag} bg="info" className="me-1">
                      {tag}
                    </Badge>
                  ))}
                </td>
                <td>{trip.splitTrips ? trip.splitTrips.length : 0}</td>
                <td>
                  {/* Placeholder for analytics/status indicators */}
                  <Badge bg="warning" text="dark">Coming Soon</Badge>
                </td>
                <td>
                  <Button
                    size="sm"
                    variant="outline-primary"
                    className="me-1"
                    onClick={() => onView && onView(trip)}
                  >
                    View
                  </Button>
                  <Button
                    size="sm"
                    variant="outline-warning"
                    className="me-1"
                    onClick={() => onEdit && onEdit(trip)}
                  >
                    Edit
                  </Button>
                  <Button
                    size="sm"
                    variant="outline-success"
                    className="me-1"
                    onClick={() => onSplit && onSplit(trip)}
                  >
                    Split
                  </Button>
                  {/* <Button
                    size="sm"
                    variant="outline-info"
                    onClick={() => onAutoCreate && onAutoCreate(trip)}
                  >
                    Auto-Create
                  </Button> */}
                </td>
              </tr>
            ))
          )}
        </tbody>
      </Table>
    </div>
  );
};

export default TripList; 