import React, { useState } from "react";
import { Card, Badge, Button, Form, InputGroup } from "react-bootstrap";

const TripPermissions = ({ permissions = [], onChange }) => {
  const [newPerm, setNewPerm] = useState("");

  const handleAdd = () => {
    if (newPerm && !permissions.includes(newPerm)) {
      onChange && onChange([...permissions, newPerm]);
      setNewPerm("");
    }
  };

  const handleRemove = (perm) => {
    onChange && onChange(permissions.filter((p) => p !== perm));
  };

  return (
    <Card>
      <Card.Header>
        <h5 className="mb-0">Trip Permissions</h5>
      </Card.Header>
      <Card.Body>
        <div className="mb-3">
          {permissions.length === 0 ? (
            <span className="text-muted">No permissions</span>
          ) : (
            permissions.map((perm) => (
              <Badge key={perm} bg="info" className="me-2 mb-2">
                {perm}
                <Button
                  size="sm"
                  variant="link"
                  className="p-0 ms-1 align-baseline"
                  onClick={() => handleRemove(perm)}
                  aria-label={`Remove ${perm}`}
                  style={{ color: "#fff", textDecoration: "none" }}
                >
                  ×
                </Button>
              </Badge>
            ))
          )}
        </div>
        <InputGroup className="mb-2" style={{ maxWidth: 300 }}>
          <Form.Control
            type="text"
            value={newPerm}
            onChange={(e) => setNewPerm(e.target.value)}
            placeholder="Add permission"
            onKeyDown={(e) => { if (e.key === "Enter") { e.preventDefault(); handleAdd(); } }}
          />
          <Button variant="primary" onClick={handleAdd}>
            Add
          </Button>
        </InputGroup>
      </Card.Body>
    </Card>
  );
};

export default TripPermissions; 