import React from "react";
import { Card, Badge, Table, Button, Row, Col, ListGroup } from "react-bootstrap";
import RoutePlanner from "./RoutePlanner";
import RoutePlayback from "./RoutePlayback";

const statusColors = {
  LIVE: "success",
  SCHEDULED: "primary",
  COMPLETED: "secondary",
  CANCELLED: "danger",
};

const TripDetails = ({ trip, onClose }) => {
  if (!trip) return null;

  return (
    <Card>
      <Card.Header className="d-flex justify-content-between align-items-center">
        <div>
          <h4 className="mb-0">{trip.title}</h4>
          <Badge bg={statusColors[trip.status] || "secondary"} className="ms-2">
            {trip.status}
          </Badge>
          {trip.instant && (
            <Badge bg="warning" text="dark" className="ms-2">
              Instant Trip
            </Badge>
          )}
        </div>
        {onClose && (
          <Button variant="secondary" onClick={onClose}>
            Close
          </Button>
        )}
      </Card.Header>
      <Card.Body>
        <Row>
          <Col md={6}>
            <h6>Description</h6>
            <p>{trip.description || <span className="text-muted">No description</span>}</p>
            <h6>Vehicle</h6>
            <p>{trip.vehicle?.name || <span className="text-muted">-</span>}</p>
            <h6>Driver</h6>
            <p>{trip.driver?.name || <span className="text-muted">-</span>}</p>
            <h6>Schedule</h6>
            <p>
              {trip.schedule?.type === "recurring"
                ? `Recurring (${trip.schedule.cron || "-"})`
                : "One-time"}
            </p>
            <h6>Tags</h6>
            <div>
              {trip.tags?.length ? (
                trip.tags.map((tag) => (
                  <Badge key={tag} bg="info" className="me-1">
                    {tag}
                  </Badge>
                ))
              ) : (
                <span className="text-muted">No tags</span>
              )}
            </div>
            <h6 className="mt-3">Created / Updated</h6>
            <div>
              <small>Created: {trip.createdAt ? new Date(trip.createdAt).toLocaleString() : "-"}</small>
              <br />
              <small>Updated: {trip.updatedAt ? new Date(trip.updatedAt).toLocaleString() : "-"}</small>
            </div>
          </Col>
          <Col md={6}>
            <h6>Source</h6>
            <p>
              <strong>{trip.source?.name}</strong>
              <br />
              <span className="text-muted">{trip.source?.address}</span>
            </p>
            <h6>Destination</h6>
            <p>
              <strong>{trip.destination?.name}</strong>
              <br />
              <span className="text-muted">{trip.destination?.address}</span>
            </p>
            <h6>Stops (Sub-trips)</h6>
            {trip.stops?.length ? (
              <ListGroup>
                {trip.stops.map((stop, idx) => (
                  <ListGroup.Item key={idx}>
                    <strong>{stop.name}</strong>
                    <br />
                    <span className="text-muted">{stop.address}</span>
                  </ListGroup.Item>
                ))}
              </ListGroup>
            ) : (
              <span className="text-muted">No stops</span>
            )}
          </Col>
        </Row>
      </Card.Body>
    </Card>
  );
};

export default TripDetails; 