import React, { useState } from "react";
import {
  Card,
  Row,
  Col,
  Badge,
  Form,
  Button,
} from "react-bootstrap";
import { useNavigate } from "react-router-dom";
import { useDispatch } from "react-redux";
import { switchClient } from "../../slices/authSlice";
import { ROLE_PERMISSIONS, ROLES } from "../../routes/permissions";
import ViewModuleIcon from "@mui/icons-material/ViewModule";
import ViewListIcon from "@mui/icons-material/ViewList";
import ButtonGroup from "react-bootstrap/ButtonGroup";
import Table from "react-bootstrap/Table";

const dummyClients = [
  {
    id: 1,
    name: "Acme Corp",
    createdAt: "2023-01-10",
    enabled: true,
    activePlan: "Premium",
    contactPerson: "Alice Smith",
    billingDetails: "alice@acme.com, 123-456-7890, 123 Main St",
  },
  {
    id: 2,
    name: "Beta Solutions",
    createdAt: "2023-02-15",
    enabled: false,
    activePlan: "Basic",
    contactPerson: "Bob Johnson",
    billingDetails: "bob@beta.com, 555-123-4567, 456 Oak Ave",
  },
];

const SwitchClientPage = () => {
  const [clients] = useState(dummyClients);
  const [search, setSearch] = useState("");
  const [view, setView] = useState("grid");
  const navigate = useNavigate();
  const dispatch = useDispatch();

  const filteredClients = clients.filter((client) =>
    client.name.toLowerCase().includes(search.toLowerCase()) ||
    client.contactPerson.toLowerCase().includes(search.toLowerCase())
  );

  const handleSelectClient = (client) => {
    // Simulate dynamic permissions based on client.activePlan
    let permissions = [];
    if (client.activePlan === "Premium") {
      permissions = ROLE_PERMISSIONS[ROLES.ADMIN];
    } else if (client.activePlan === "Basic") {
      permissions = ROLE_PERMISSIONS[ROLES.CUSTOMER];
    } else {
      permissions = [];
    }
    dispatch(switchClient({ client, permissions }));
    navigate(`/client/${client.id}/dashboard`);
  };

  return (
    <div>
      <div className="d-flex justify-content-between align-items-center mb-4">
        <h2>Switch Client</h2>
        <ButtonGroup>
          <Button
            variant={view === "grid" ? "primary" : "outline-primary"}
            onClick={() => setView("grid")}
            title="Grid View"
          >
            <ViewModuleIcon />
          </Button>
          <Button
            variant={view === "list" ? "primary" : "outline-primary"}
            onClick={() => setView("list")}
            title="List View"
          >
            <ViewListIcon />
          </Button>
        </ButtonGroup>
      </div>
      <Form.Group className="mb-3">
        <Form.Control
          type="text"
          placeholder="Search clients by name or contact..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
      </Form.Group>
      {view === "grid" ? (
        <Row>
          {filteredClients.map((client) => (
            <Col key={client.id} lg={6} className="mb-4">
              <Card>
                <Card.Header className="d-flex justify-content-between align-items-center">
                  <div>
                    <h5 className="mb-0">
                      <Button
                        variant="link"
                        className="p-0 align-baseline"
                        style={{ textDecoration: "underline" }}
                        onClick={() => handleSelectClient(client)}
                      >
                        {client.name}
                      </Button>
                    </h5>
                    <Badge bg={client.enabled ? "success" : "secondary"}>
                      {client.enabled ? "Enabled" : "Disabled"}
                    </Badge>
                  </div>
                </Card.Header>
                <Card.Body>
                  <div><strong>Contact:</strong> {client.contactPerson}</div>
                  <div><strong>Active Plan:</strong> {client.activePlan}</div>
                  <div><strong>Billing:</strong> {client.billingDetails}</div>
                  <div><strong>Created At:</strong> {client.createdAt}</div>
                </Card.Body>
              </Card>
            </Col>
          ))}
        </Row>
      ) : (
        <Card>
          <Card.Body>
            <Table responsive striped hover>
              <thead>
                <tr>
                  <th>Name</th>
                  <th>Contact</th>
                  <th>Active Plan</th>
                  <th>Billing</th>
                  <th>Enabled</th>
                  <th>Created At</th>
                </tr>
              </thead>
              <tbody>
                {filteredClients.map((client) => (
                  <tr key={client.id}>
                    <td>
                      <Button
                        variant="link"
                        className="p-0 align-baseline"
                        style={{ textDecoration: "underline" }}
                        onClick={() => handleSelectClient(client)}
                      >
                        {client.name}
                      </Button>
                    </td>
                    <td>{client.contactPerson}</td>
                    <td>{client.activePlan}</td>
                    <td>{client.billingDetails}</td>
                    <td>
                      <Badge bg={client.enabled ? "success" : "secondary"}>
                        {client.enabled ? "Enabled" : "Disabled"}
                      </Badge>
                    </td>
                    <td>{client.createdAt}</td>
                  </tr>
                ))}
              </tbody>
            </Table>
          </Card.Body>
        </Card>
      )}
    </div>
  );
};

export default SwitchClientPage; 